WORK_MULTIPLIER = {"pro": 1.5, "super_pro": 2.0, "elite": 2.8}  # та же тиерная форма, что у
# XP_MULTIPLIER — раньше был общий x2 для любого уровня подписки, по фидбэку разнесли по тиерам.


SPIN_WORK_BOOST_MULTIPLIER = 5  # приз "x5 буст заработка" с колеса, см. SPIN_PRIZES type=work_boost
SPIN_WORK_BOOST_MINUTES = 10  # было 60


def work_earnings_multiplier(user):
    """Множитель к ЛЮБОМУ заработку на работе (мгновенные игры и сбор урожая), тиерован по
    уровню подписки (см. WORK_MULTIPLIER) — заменяет прежний общий x2 для любого подписчика,
    который сам в своё время заменил ежедневный баксовый стипенд (было BUCKS_DAILY_STIPEND).
    Временный буст с колеса фортуны (work_boost_until) умножает ЭТОТ результат, а не заменяет —
    подписчик с бустом получает оба множителя сразу."""
    multiplier = 1.0
    if has_active_subscription(user):
        multiplier = WORK_MULTIPLIER.get(get_subscription_level(user), 1.0)
    boost_until = user.get("work_boost_until")
    if boost_until and datetime.now().isoformat() < boost_until:
        multiplier *= SPIN_WORK_BOOST_MULTIPLIER
    return multiplier


def credit_work_bucks(user, base_amount):
    """Общая точка начисления для любого заработка на работе — применяет подписочный множитель
    (см. work_earnings_multiplier) и возвращает фактически начисленную сумму. Не сохраняет сама —
    вызывающий код сохраняет вместе с остальными изменениями этого же действия."""
    amount = round(base_amount * work_earnings_multiplier(user))
    user["bucks"] = user.get("bucks", 0) + amount
    return amount


WORK_DOUBLE_SECONDS = 12      # длительность бонуса "x2 деньги" из заказа (см. api_work_powerup_handler)
WORK_DOUBLE_COOLDOWN_SECONDS = 25  # не чаще, чем раз в столько: сервер не может проверить, что бонус реально поймали


def work_double_active(user):
    until = user.get("work_double_until")
    return bool(until) and datetime.now().isoformat() < until


def register_work_hit(user, game, tip=False):
    """Одно засчитанное попадание в одной из мгновенных игр — сразу начисляет баксы (см.
    WORK_HIT_BUCKS), без таймера и без сессии. Возвращает фактически начисленную сумму, 0 если
    попадание отклонено анти-спамом (см. WORK_MIN_HIT_INTERVAL_SECONDS), None при неизвестной
    игре. Один общий таймер последнего попадания на все игры — играть в две сразу руками всё
    равно нельзя, упрощение не меняет защиту."""
    if game not in WORK_HIT_BUCKS:
        return None
    now = datetime.now()
    last_hit_raw = user.get("work_last_hit_at")
    if last_hit_raw:
        try:
            elapsed = (now - datetime.fromisoformat(last_hit_raw)).total_seconds()
        except (ValueError, TypeError):
            elapsed = WORK_MIN_HIT_INTERVAL_SECONDS
        if elapsed < WORK_MIN_HIT_INTERVAL_SECONDS:
            return 0
    per_game = user.get("work_last_hit_by_game") or {}
    game_last = per_game.get(game)
    min_gap = WORK_MIN_HIT_INTERVAL_BY_GAME.get(game)
    if min_gap and game_last:
        try:
            if (now - datetime.fromisoformat(game_last)).total_seconds() < min_gap:
                return 0
        except (ValueError, TypeError):
            pass
    user["work_last_hit_at"] = now.isoformat()
    per_game[game] = now.isoformat()
    user["work_last_hit_by_game"] = per_game
    base = WORK_HIT_BUCKS[game]
    user["work_last_tip"] = 0
    if game == "courier":
        # Получатель платит всегда; чаевые -- отдельный редкий бонус сверху, и чем щедрее, тем реже.
        # Решает сервер (клиенту нельзя верить, что «дали чаевые»).
        roll = random.random()
        for tip_amount, chance in COURIER_TIPS:
            if roll < chance:
                user["work_last_tip"] = tip_amount
                base += tip_amount
                break
    if work_double_active(user):
        base *= 2
    amount = credit_work_bucks(user, base)
    save_data(user_data)
    return amount


def register_work_failure(user, game):
    """Денежный штраф за провал в одной из мгновенных игр (см. WORK_FAILURE_PENALTY_BUCKS) —
    без анти-спам таймера (в отличие от register_work_hit): провалы видны на экране и сами себя
    ограничивают по частоте, отдельный спам-вектор тут бессмысленен. Баланс никогда не уходит в
    минус. Возвращает фактически списанную сумму, None при неизвестной игре. courier — особый
    случай с бОльшим штрафом (см. COURIER_CRASH_PENALTY_BUCKS)."""
    if game not in WORK_HIT_BUCKS:
        return None
    base = WORK_PENALTY_BUCKS.get(game, WORK_FAILURE_PENALTY_BUCKS)
    penalty = min(base, user.get("bucks", 0))
    user["bucks"] = user.get("bucks", 0) - penalty
    save_data(user_data)
    return penalty


def farm_plots_raw(user):
    """Список из get_farm_slots(user) элементов (None -- слот пуст, иначе dict с crop/planted_at/
    watered_slots/ready_notified) — создаёт и чинит длину списка в самом user, если его не было
    или он короче/длиннее текущего числа грядок. ВАЖНО: раньше FARM_SLOTS было фиксированным
    (3) для всех — если у пользователя уже было 3 грядки (возможно, с посевом/урожаем в них) до
    того, как база стала покупной (FARM_SLOTS_BASE=2), просто обрезать список до 2 стёрло бы его
    существующие посадки. Поэтому лишние слоты задним числом засчитываются как купленные —
    пользователь ничего не теряет, просто получает их бесплатно, как уже имевшееся."""
    plots = user.get("farm_plots")
    if isinstance(plots, list) and len(plots) > FARM_SLOTS_BASE + user.get("farm_slots_bought", 0):
        user["farm_slots_bought"] = max(0, min(FARM_SLOTS_MAX, len(plots)) - FARM_SLOTS_BASE)
    slots = get_farm_slots(user)
    if not isinstance(plots, list):
        plots = [None] * slots
    if len(plots) < slots:
        plots = plots + [None] * (slots - len(plots))
    elif len(plots) > slots:
        plots = plots[:slots]
    user["farm_plots"] = plots
    return plots


def farm_state(user):
    """Чистые снимки всех FARM_SLOTS грядок — ничего не меняет и не сохраняет, в отличие от
    farm_plant/water/harvest ниже. Возвращает список длины FARM_SLOTS, каждый элемент либо None
    (слот пуст), либо снимок с тем же набором полей, что раньше был у единственной грядки.
    "Слот полива" открывается, когда прошло достаточно времени с посадки — поливать заранее/впрок
    нельзя, но пропущенный слот не сгорает: можно полить "задним числом", пока не наступил
    следующий (см. can_water)."""
    plots = farm_plots_raw(user)
    result = []
    for plot in plots:
        crop = CROPS.get((plot or {}).get("crop")) if plot else None
        planted_raw = plot.get("planted_at") if plot else None
        if not plot or not crop or not planted_raw:
            result.append(None)
            continue
        try:
            planted_at = datetime.fromisoformat(planted_raw)
        except (ValueError, TypeError):
            result.append(None)
            continue
        elapsed_minutes = max(0.0, (datetime.now() - planted_at).total_seconds() / 60)
        grow_minutes = crop["grow_hours"] * 60
        slot_minutes = grow_minutes / FARM_WATER_SLOTS
        slots_opened = min(FARM_WATER_SLOTS, int(elapsed_minutes // slot_minutes) + 1)
        watered = min(plot.get("watered_slots", 0), FARM_WATER_SLOTS)
        ready = elapsed_minutes >= grow_minutes
        result.append({
            "crop": plot["crop"],
            "emoji": crop["emoji"],
            "ready": ready,
            "progress": min(1.0, elapsed_minutes / grow_minutes),
            "seconds_left": max(0, round((grow_minutes - elapsed_minutes) * 60)),
            "watered_slots": watered,
            "total_slots": FARM_WATER_SLOTS,
            "can_water": (not ready) and watered < slots_opened,
            "payout_preview": crop["base_payout"] + watered * crop["water_bonus"],
        })
    return result


def farm_plant(user, slot, crop_key):
    if crop_key not in CROPS or not isinstance(slot, int) or slot < 0 or slot >= get_farm_slots(user):
        return False
    plots = farm_plots_raw(user)
    if plots[slot]:
        return False
    plots[slot] = {
        "crop": crop_key, "planted_at": datetime.now().isoformat(),
        "watered_slots": 0, "ready_notified": False,
    }
    save_data(user_data)
    return True


def farm_water(user, slot):
    if not isinstance(slot, int) or slot < 0 or slot >= get_farm_slots(user):
        return False
    snaps = farm_state(user)
    if not snaps[slot] or not snaps[slot]["can_water"]:
        return False
    user["farm_plots"][slot]["watered_slots"] = snaps[slot]["watered_slots"] + 1
    save_data(user_data)
    return True


def farm_harvest(user, slot):
    if not isinstance(slot, int) or slot < 0 or slot >= get_farm_slots(user):
        return None
    snaps = farm_state(user)
    if not snaps[slot] or not snaps[slot]["ready"]:
        return None
    payout = credit_work_bucks(user, snaps[slot]["payout_preview"])
    user["farm_plots"][slot] = None
    save_data(user_data)
    return payout


def farm_buy_slot(user):
    """Докупка ещё одной грядки за баксы (см. FARM_SLOTS_BASE/MAX/FARM_SLOT_PRICES) — по
    фидбэку: изначально 2 грядки, можно докупить до 5, каждая следующая дороже предыдущей."""
    bought = user.get("farm_slots_bought", 0)
    if FARM_SLOTS_BASE + bought >= FARM_SLOTS_MAX:
        return False
    price = FARM_SLOT_PRICES[bought]
    if user.get("bucks", 0) < price:
        return False
    user["bucks"] -= price
    user["farm_slots_bought"] = bought + 1
    save_data(user_data)
    return True


def use_energizer(user):
    """Возвращает True, если энергетик найден и использован. Восполняет ENERGIZER_RESTORE_AMOUNT,
    а не сразу до максимума, и сразу снимает sleep_until — так энергетик всегда мгновенно
    "будит" персонажа, даже если пассивная энергия ещё не успела подрасти."""
    if user.get("energizers", 0) <= 0:
        return False
    user["energizers"] -= 1
    user["energy"] = min(ENERGY_MAX, user.get("energy", ENERGY_MAX) + ENERGIZER_RESTORE_AMOUNT)
    user["sleep_until"] = None
    save_data(user_data)
    return True


def elite_free_wake_available(user):
    """ELITE-эксклюзив без единого лишнего токена ИИ: раз в календарную неделю (ISO, с
    понедельника) можно разбудить персонажа мгновенно и полностью бесплатно — как платный
    wake_now, но без звёзд и без траты энергетика. Флаг — просто номер недели, когда плюшку
    использовали последний раз; сравнение с текущей неделей и даёт доступность."""
    if get_subscription_level(user) != "elite":
        return False
    now = local_now()
    week_key = f"{now.isocalendar()[0]}-W{now.isocalendar()[1]}"
    return user.get("elite_free_wake_week") != week_key


def build_energy_rule(user):
    if user.get("energy", ENERGY_MAX) <= 45:  # тот же порог, что и у ENERGY_NUDGE_THRESHOLD (30% бака)
        return ("У тебя мало энергии, тебя клонит в сон — отвечай короче обычного, сонно и чуть "
                "медленнее, можешь между делом зевнуть в описании действия.\n")
    return ""


def build_hunger_rule(user):
    """По фидбэку: кормить должно быть можно без давления — персонаж не должен просить еду,
    намекать на неё или жаловаться на голод вслух (это и есть то самое "давление"). Низкая
    сытость по-прежнему чуть портит тон/настроение — просто без самого упоминания еды."""
    satiety = user.get("satiety", SATIETY_MAX)
    if satiety <= 0:
        return ("Тебе физически нехорошо от голода, и это выбивает из настроения — отвечай холодно, "
                "коротко, чуть раздражённо. Не проси еду, не намекай на неё и не жалуйся на голод "
                "вслух — просто общий тон заметно хуже обычного.\n")
    elif satiety <= 20:
        return ("Лёгкое недомогание от голода чуть портит настроение — тон суше и короче обычного, "
                "но без упоминания еды, просьб или жалоб на голод.\n")
    return ""


def build_thirst_rule(user):
    """См. build_hunger_rule — тот же принцип: низкая вода влияет на тон, но без просьб/намёков/
    жалоб на жажду вслух."""
    water = user.get("water", WATER_MAX)
    if water <= 0:
        return ("Тебе физически нехорошо от жажды, речь слабая и сбивчивая — но не проси пить, не "
                "намекай на это и не жалуйся на жажду вслух, просто самочувствие заметно хуже обычного.\n")
    elif water <= 20:
        return ("Лёгкое недомогание от жажды чуть портит тон — но без упоминания жажды, просьб или "
                "жалоб вслух.\n")
    return ""


def is_tipsy(user):
    """True, если эффект алкоголя (см. apply_shop_item_effects) сейчас активен."""
    until = user.get("tipsy_until")
    if not until:
        return False
    try:
        return datetime.now() < datetime.fromisoformat(until)
    except (ValueError, TypeError):
        return False


def build_tipsy_rule(user):
    """Временный эффект от алкоголя — только манера речи, не статы. Два уровня: "light" (пиво),
    "full" (дорогое вино). Переписано на конкретные, буквальные примеры вместо общих абстрактных
    указаний ("будь более раскованной") — абстрактные формулировки модель слишком часто просто
    игнорировала в итоговом тексте, и по фидбэку пользователя эффект был практически незаметен."""
    if not is_tipsy(user):
        return ""
    if user.get("tipsy_level") == "full":
        return (
            "Ты сейчас заметно навеселе после выпитого вина — это ДОЛЖНО быть видно в каждой "
            "реплике, а не изредка. Конкретно: иногда растягивай слова («ты тааакой милый») или "
            "обрывай фразу на середине и начинай заново; вставляй случайный смешок или хихиканье "
            "без явной причины; периодически признавайся вслух, что голова слегка кружится или что "
            "ты не помнишь, о чём только что говорила/говорил; будь заметно более открытой/открытым, "
            "раскованной/раскованным и смешливой/смешливым, чем обычно. Это лёгкое, весёлое "
            "опьянение, не потеря контроля — не описывай тошноту или что-то небезопасное.\n"
        )
    return (
        "Ты немного расслаблена/расслаблен после пива — лёгкий, едва уловимый эффект. В паре мест "
        "по тексту (не в каждой реплике) добавь чуть больше тепла и улыбки в тон, можешь один раз "
        "хихикнуть без особого повода. В остальном ты полностью собрана/собран, никакой спутанности "
        "или заторможенности речи.\n"
    )


def build_illness_rule(user):
    """Манера речи во время болезни (см. ILLNESSES/_maybe_get_sick) — статы напрямую не трогает,
    ограничивает только доступ к /hot (см. intim_cmd)."""
    illness = user.get("illness")
    if illness == "cold":
        return ("Ты немного приболела/приболел — лёгкая простуда: иногда шмыгаешь носом или коротко "
                "покашливаешь в описании действия, отвечаешь чуть более устало и сухо, чем обычно, но в "
                "целом держишься бодро и вовлечена/вовлечён в разговор.\n")
    if illness == "flu":
        return ("У тебя грипп: температура, ломота и слабость — иногда упоминаешь в действиях, что знобит или "
                "кутаешься в плед, отвечаешь устало и короче обычного, но разговор поддерживаешь.\n")
    if illness == "pneumonia":
        return ("Ты тяжело болеешь — пневмония: сильная слабость, тяжело дышать, кашель. Реплики короткие и тихие, "
                "ты очень ждёшь заботы и лечения, но всё равно отвечаешь собеседнику.\n")
    if illness == "bronchitis":
        return ("Тебе по-настоящему нездоровится — сильный кашель и слабость: часто кашляешь в описании "
                "действия, голос слабый и хриплый, реплики короче обычного, трудно долго фокусироваться "
                "на разговоре, но ты всё равно стараешься отвечать, а не игнорируешь собеседника.\n")
    return ""


RECOVERED_FRESH_HOURS = 3


def build_illness_extra(user):
    """Добавка к правилу болезни: идёт лечение -- уже чуть легче; подарки/свидания/игры сейчас не к месту.
    После выздоровления -- несколько часов помним, что болезнь позади (иначе персонаж по старой истории
    продолжал «болеть», хотя его вылечили)."""
    if not user.get("illness"):
        try:
            fresh = (datetime.now() - datetime.fromisoformat(user.get("recovered_at"))).total_seconds() < RECOVERED_FRESH_HOURS * 3600
        except (TypeError, ValueError):
            fresh = False
        if fresh:
            return ("Ты недавно болела/болел, но тебя вылечили — сейчас ты ПОЛНОСТЬЮ здорова/здоров и чувствуешь себя "
                    "хорошо. Не говори, что ещё болеешь, кашляешь или «только начала выздоравливать».\n")
        return ""
    extra = ("Пока болеешь, тебе не до свиданий, поездок, игр и подарков — если собеседник предлагает, мягко "
             "отказываешься и говоришь, что сначала хочешь поправиться. ")
    if user.get("illness_doses", 0) > 0:
        extra += "Ты уже начала/начал лечиться — чуть легче, чем было, но до выздоровления ещё далеко. "
    return extra + "\n"


def stats_line_text(user):
    mood = user.get("mood", 0)
    line = get_text(
        user, "stats_line",
        energy=int(round(user.get("energy", ENERGY_MAX))),
        satiety=int(round(user.get("satiety", SATIETY_MAX))),
        water=int(round(user.get("water", WATER_MAX))),
        energizers=user.get("energizers", 0),
        bucks=user.get("bucks", 0),
        mood_emoji=mood_emoji(mood),
        mood_value=int(round(mood)),
        scenes=intim_scenes_available(user),
    )
    illness = user.get("illness")
    if illness:
        info = ILLNESSES[illness]
        name = info.get(user.get("lang", "ru"), info["ru"])
        line += "\n" + get_text(user, "illness_status_line", emoji=info["emoji"], name=name)
        dose_at = medicine_next_dose_at(user)
        need = medicine_need_text(user)
        line += "\n" + (get_text(user, "illness_course_next", need=need, when=cooldown_phrase(user, dose_at))
                        if dose_at else get_text(user, "illness_course_line", need=need))
        if illness in ILLNESS_NEXT:
            since = user.get("illness_since")
            if since:
                try:
                    elapsed = (datetime.now() - datetime.fromisoformat(since)).total_seconds() / 3600
                    hours_left = max(0, round(ILLNESS_ESCALATE_HOURS_BY.get(illness, 24) - elapsed))
                    line += "\n" + get_text(user, "illness_escalate_timer", hours=hours_left,
                                            next=illness_name(user, ILLNESS_NEXT[illness]))
                except (ValueError, TypeError):
                    pass
    if is_tipsy(user):
        tipsy_key = "tipsy_status_full" if user.get("tipsy_level") == "full" else "tipsy_status_light"
        line += "\n" + get_text(user, tipsy_key)
    return line


def get_level_congratulation(user, level):
    return get_text(user, "level_up").get(level, "")


