def get_style_kb(user):
    buttons = []
    for key in STYLES:
        label = style_display_label(key, user)
        if not is_style_unlocked(key, user):
            label += " 🔒"
        buttons.append(InlineKeyboardButton(text=label, callback_data=f"style_{key}"))
