def get_full_kb(user):
    if APP_MODE:
        # Всё теперь в приложении -- старую клавиатуру (Магазин/Колесо/Работа...) убираем.
        return ReplyKeyboardRemove(remove_keyboard=True)
    return _legacy_full_kb(user)


def _legacy_full_kb(user):
    # "Редактировать" убрана совсем — то же самое теперь доступно через нативный жест
    # редактирования сообщения в самом Телеграме (см. handle_edited_message), отдельная кнопка
    # для этого больше не нужна. На её месте теперь "Наш канал" (было выше), а на месте "Наш
    # канал" — "Магазин".
    #
    # ВАЖНО: обе кнопки — ПРОСТОЙ текст, без web_app= напрямую здесь, даже когда WEBAPP_URL
    # настроен. Это не упрощение "на будущее" — это обход документированного ограничения самого
    # Телеграма: Telegram.WebApp.initData ГАРАНТИРОВАННО пустая, если Mini App открыт через
    # web_app на кнопке ПОСТОЯННОЙ reply-клавиатуры (в отличие от кнопки в инлайн-клавиатуре
    # конкретного сообщения) — см. https://core.telegram.org/bots/webapps, раздел про initData
    # ("It is empty if the Mini App was launched from a keyboard button..."). Именно из-за этого
    # "Магазин"/"Колесо фортуны"/"Работа" в этой клавиатуре стабильно ловили "Invalid Telegram
    # signature" у реальных пользователей, сколько код ни проверяй и как клавиатуру ни обновляй —
    # initData тут в принципе не может прийти, это не баг конкретной реализации. Поэтому тут —
    # обычные текстовые кнопки; сам переход в Mini App происходит в их хендлерах (shop_reply,
    # spin_button_handler -> send_spin_menu, work_reply -> send_work_menu), которые шлют СВЕЖЕЕ
    # сообщение с инлайн-кнопкой — у инлайн-кнопок initData приходит нормально.
    shop_button = KeyboardButton(text=get_text(user, "shop_btn"), style="success")
    spin_button = KeyboardButton(text=get_text(user, "spin_wheel"))
    work_button = KeyboardButton(text=get_text(user, "work_btn"))
    hot_button = KeyboardButton(text=get_text(user, "hot_btn"), style="danger")
    return ReplyKeyboardMarkup(
        keyboard=[
            [KeyboardButton(text=get_text(user, "main_menu")), KeyboardButton(text=get_text(user, "my_profile"))],
            [spin_button, shop_button, work_button],
            [hot_button],
            [KeyboardButton(text=get_text(user, "our_channel"), style="primary"),
             KeyboardButton(text=get_text(user, "support_btn"))]
        ],
        resize_keyboard=True
    )


def get_main_menu_keyboard(user):
    buttons = [[InlineKeyboardButton(text=get_text(user, "open_app_btn"), web_app=WebAppInfo(url=f"{WEBAPP_URL}/app"),
                                     style="success")]] if WEBAPP_URL else []
    buttons += [
        [InlineKeyboardButton(text=get_text(user, "change_character"), callback_data="main_change", style="primary")],
        [InlineKeyboardButton(text=get_text(user, "invite_friend"), callback_data="referral_menu")]
    ]
    if get_subscription_level(user) in ("super_pro", "elite"):
        buttons.append([InlineKeyboardButton(text=get_text(user, "create_character"), callback_data="create_character")])
    else:
        buttons.append([InlineKeyboardButton(text="🔒 " + get_text(user, "create_character") + " (SUPER PRO/ELITE)", callback_data="create_character_locked")])
    return InlineKeyboardMarkup(inline_keyboard=buttons)


def get_profile_keyboard(user):
    # Магазин еды/подарков сюда больше не выводим — профиль теперь только про покупки баксов
    # (подписка/сцены) и переключатель уведомлений; сам магазин (включая энергетики) живёт в
    # главной reply-клавиатуре (см. get_full_kb), там же, где колесо фортуны.
    mute_key = "notifications_off_btn" if user.get("notifications_muted") else "notifications_on_btn"
    rows = [
        [InlineKeyboardButton(text=get_text(user, "subscribe"), callback_data="profile_subs", style="success")],
        [InlineKeyboardButton(text=get_text(user, "intim_buy_btn", price=price_label("intim_scene", user)), callback_data="buy:intim_scene", style="success")],
        [InlineKeyboardButton(text=get_text(user, mute_key), callback_data="toggle_notifications", style="primary")],
    ]
    # Иммунитет к болезням — перк именно ELITE (самый верхний тариф), не SUPER PRO. Кнопка теперь
    # видна ВСЕМ (не только ELITE) — иначе о фиче просто никто не узнаёт; не-ELITE видит
    # заблокированный вариант с припиской "(ELITE)", нажатие даёт alert с реальным требованием
    # (см. toggle_illness_immunity, он и так уже перепроверяет уровень подписки на сервере).
    if get_subscription_level(user) == "elite":
        immunity_key = "illness_immunity_on_btn" if user.get("illness_disabled") else "illness_immunity_off_btn"
        rows.append([InlineKeyboardButton(text=get_text(user, immunity_key), callback_data="toggle_illness_immunity", style="primary")])
    else:
        rows.append([InlineKeyboardButton(text="🔒 " + get_text(user, "illness_immunity_off_btn") + " (ELITE)", callback_data="toggle_illness_immunity")])
    rows.append([InlineKeyboardButton(text=get_text(user, "back"), callback_data="profile_back", style="danger")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def safe_delete(message: types.Message):
    """Обёртка над message.delete(), чтобы упавшее удаление (нет прав / сообщение старше 48ч)
    не прерывало весь остальной хендлер — раньше такие исключения "тихо" ломали кнопки."""
    try:
        await message.delete()
    except Exception:
        pass


# ============================================================
#  ОСНОВНОЙ СЦЕНАРИЙ РЕГИСТРАЦИИ /start
# ============================================================
async def proceed_flow(user_id: int, chat_id: int):
    """Показывает следующий шаг регистрации. В отличие от старого кода, всегда получает
    настоящий user_id и chat_id, а не message.from_user бота — это чинит главный баг:
    раньше call.message.from_user.id было ID бота, и все пользователи делили один
    общий "призрачный" профиль при переходе между шагами регистрации."""
    user = get_user(user_id)

    if not user.get("lang"):
        await bot.send_message(chat_id, TEXTS["ru"]["choose_lang"], reply_markup=get_lang_kb(), parse_mode="Markdown")
        return

    if not user["verified"]:
        await bot.send_message(chat_id, get_text(user, "age_confirm"), reply_markup=get_age_kb(user), parse_mode="Markdown")
        return

    if not user["agreement_accepted"]:
        # Раньше тут было два шага (сначала отдельная кнопка "Открыть соглашение", и только
        # после неё — "Принимаю/Не принимаю") специально для защиты от мгновенного "дабл-тапа"
        # мимо текста. По фидбэку первый шаг убрали как лишний — показываем решение сразу, но
        # agreement_opened_at всё равно проставляем здесь же, так что AGREEMENT_MIN_READ_SECONDS
        # (см. agreement_accept) по-прежнему отсекает мгновенное нажатие "Принимаю".
        if not user.get("agreement_opened_at"):
            user["agreement_opened_at"] = datetime.now().isoformat()
            save_data(user_data)
        await bot.send_message(chat_id, get_text(user, "agreement_intro"), reply_markup=get_agreement_kb(user))
        return

    if APP_MODE and not user["personality_ready"]:
        # Регистрация закончена здесь, персонажа (мир, пол, характер) создаём уже в приложении.
        await bot.send_message(chat_id, get_text(user, "app_create_character"), reply_markup=app_open_kb(user, "app_create_btn"))
        return

    if not user.get("world"):
        await bot.send_message(chat_id, get_text(user, "choose_world"), reply_markup=get_world_kb(user), parse_mode="Markdown")
        return

    if not user.get("user_gender"):
        await bot.send_message(chat_id, get_text(user, "choose_gender"), reply_markup=get_user_gender_kb(user))
        return

    if not user["personality_ready"]:
        await bot.send_message(chat_id, get_text(user, "choose_style"), reply_markup=get_style_kb(user), parse_mode="Markdown")
        return

    if not APP_MODE:
        await bot.send_message(chat_id, get_text(user, "welcome"), reply_markup=get_full_kb(user))
    await send_main_menu(chat_id, user)


@dp.message(Command("start"))
async def start_cmd(message: types.Message):
    if maintenance_mode and message.from_user.id not in ADMIN_IDS:
        user = get_user(message.from_user.id)
        await message.answer(get_text(user, "maintenance"), parse_mode="Markdown")
        return

    user = get_user(message.from_user.id)

    # Реферальная ссылка — разбираем только из настоящего /start-сообщения пользователя,
    # а не из переиспользованного message бота (как было раньше).
    args = message.text.split() if message.text else []
    if not user.get("first_seen"):
        user["first_seen"] = datetime.now().isoformat()
        # Метка рекламы: t.me/<бот>?start=telega1 -> source="telega1" (запоминаем только первую), см. /stats.
        if len(args) > 1:
            user["source"] = "ref" if args[1].startswith("ref_") else re.sub(r"[^a-zA-Z0-9_-]", "", args[1])[:32] or None
        save_data(user_data)
    if len(args) > 1 and args[1].startswith("ref_"):
        referrer_id = args[1].split("_", 1)[1]
        if str(message.from_user.id) != referrer_id and not user.get("referred_by"):
            referrer = get_user(referrer_id)
            referrer["bucks"] = referrer.get("bucks", 0) + REFERRAL_INVITER_BUCKS
            referrer["energizers"] = referrer.get("energizers", 0) + REFERRAL_INVITER_ENERGIZERS
            referrer["intim_scenes"] = referrer.get("intim_scenes", 0) + REFERRAL_INVITER_SCENES
            referrer["referral_count"] = referrer.get("referral_count", 0) + 1
            user["bucks"] = user.get("bucks", 0) + REFERRAL_INVITEE_BUCKS
            user["intim_scenes"] = user.get("intim_scenes", 0) + REFERRAL_INVITEE_SCENES
            user["bonus_spins"] = user.get("bonus_spins", 0) + REFERRAL_INVITEE_SPINS
            user["referred_by"] = referrer_id
            save_data(user_data)
            # Язык ещё не выбран на этом шаге (выбор языка идёт дальше в proceed_flow),
            # поэтому сообщение о бонусе показываем сразу на двух языках. Числа/валюты тут
            # должны совпадать с тем, что реально выдаётся выше — раньше текст остался старым
            # ("+5/+10 сообщений") уже после того, как награду поменяли на баксы/энергетики.
            await message.answer(
                f"🎉 Ты пришёл по реферальной ссылке! Тебе +{REFERRAL_INVITEE_BUCKS}💵, +{REFERRAL_INVITEE_SCENES} горячая сцена "
                f"и +{REFERRAL_INVITEE_SPINS} доп. прокрут колеса, другу — +{REFERRAL_INVITER_BUCKS}💵, "
                f"+{REFERRAL_INVITER_ENERGIZERS}⚡ и +{REFERRAL_INVITER_SCENES} горячая сцена!\n"
                f"🎉 You joined via a referral link! You get +{REFERRAL_INVITEE_BUCKS}💵, +{REFERRAL_INVITEE_SCENES} hot scene "
                f"and +{REFERRAL_INVITEE_SPINS} extra spin, your friend gets +{REFERRAL_INVITER_BUCKS}💵, "
                f"+{REFERRAL_INVITER_ENERGIZERS}⚡ and +{REFERRAL_INVITER_SCENES} hot scene!"
            )

    await proceed_flow(message.from_user.id, message.chat.id)


