def prize_name(prize, user):
    lang = user.get("lang", "ru")
    return prize.get(f"name_{lang}", prize["name"]) if lang != "ru" else prize["name"]


SPIN_LUCK_HOURS = 24
SPIN_LUCK_WEIGHT_MULT = {  # множители шансов при активной "Удаче" (см. spin_luck_active)
    "nothing": 0.3, "work_boost": 2.0, "intim_scenes": 1.6,
    "subscription_pro": 4.0, "subscription_super": 4.0, "care_package": 1.3,
}
SPIN_LUCK_JACKPOT_MULT = 4.0


def spin_luck_seconds_left(user):
    """None -- удача вечная (ELITE), 0 -- нет, иначе сколько секунд осталось от купленной."""
    if has_active_subscription(user) and get_subscription_level(user) == "elite":
        return None
    until = user.get("spin_luck_until")
    if not until:
        return 0
    try:
        return max(0, int((datetime.fromisoformat(until) - datetime.now()).total_seconds()))
    except (ValueError, TypeError):
        return 0


def spin_luck_active(user):
    left = spin_luck_seconds_left(user)
    return left is None or left > 0


def choose_spin_prize(user=None):
    """Взвешенный выбор приза — общий для чата и Mini App. Для "Удачи" (покупная на 24ч или вечная
    у ELITE) вес "ничего" режется, а редкие призы растут — сумма пересчитывается сама."""
    luck = bool(user) and spin_luck_active(user)
    weights = []
    for p in SPIN_PRIZES:
        w = p["weight"]
        if luck:
            w *= SPIN_LUCK_WEIGHT_MULT.get(p["type"], 1.0)
            if p["type"] == "bucks" and p["value"] >= 10000:
                w *= SPIN_LUCK_JACKPOT_MULT
        weights.append(w)
    return random.choices(SPIN_PRIZES, weights=weights, k=1)[0]


def apply_spin_prize(user, chosen):
    """Начисляет выигрыш и возвращает готовый локализованный текст результата — общая часть
    между чатовым колесом (spin_result) и колесом в Mini App (perform_webapp_spin)."""
    if chosen["type"] == "bucks":
        user["bucks"] = user.get("bucks", 0) + chosen["value"]
        result_text = get_text(user, "spin_win_bucks", value=chosen["value"])
    elif chosen["type"] == "energizers":
        user["energizers"] = user.get("energizers", 0) + chosen["value"]
        result_text = get_text(user, "spin_win_energizers", value=chosen["value"])
    elif chosen["type"] == "xp":
        user["xp"] = user.get("xp", 0) + chosen["value"]
        result_text = get_text(user, "spin_win_xp", value=chosen["value"])
    elif chosen["type"] == "intim_scenes":
        user["intim_scenes"] = user.get("intim_scenes", 0) + chosen["value"]
        result_text = get_text(user, "spin_win_intim", value=chosen["value"])
    elif chosen["type"] == "care_package":
        user["satiety"] = SATIETY_MAX
        user["water"] = WATER_MAX
        user["water_zero_since"] = None
        user["dehydration_warned"] = False
        user["dehydration_urgent_warned"] = False
        result_text = get_text(user, "spin_win_care_package")
    elif chosen["type"] == "subscription_pro":
        result_text = grant_spin_subscription(user, "pro", 5, "spin_win_pro")
    elif chosen["type"] == "subscription_super":
        result_text = grant_spin_subscription(user, "super_pro", 3, "spin_win_super")
    elif chosen["type"] == "work_boost":
        user["work_boost_until"] = (datetime.now() + timedelta(minutes=SPIN_WORK_BOOST_MINUTES)).isoformat()
        result_text = get_text(user, "spin_win_work_boost", minutes=SPIN_WORK_BOOST_MINUTES,
                                mult=SPIN_WORK_BOOST_MULTIPLIER)
    elif chosen["type"] == "extra_spin":
        user["bonus_spins"] = user.get("bonus_spins", 0) + chosen["value"]
        result_text = get_text(user, "spin_win_extra_spin", value=chosen["value"])
    else:
        result_text = get_text(user, "spin_nothing")
    return result_text


async def spin_result(chat_id, user, free=False):
    chosen = choose_spin_prize(user)

    msg = await bot.send_message(chat_id, get_text(user, "spin_rolling"))
    for _ in range(3):
        await asyncio.sleep(0.5)
        fake = random.choice(SPIN_PRIZES)
        try:
            await msg.edit_text(get_text(user, "spin_almost", name=prize_name(fake, user)))
        except Exception:
            pass
    await asyncio.sleep(0.8)
    await safe_delete(msg)

    result_text = apply_spin_prize(user, chosen)
    save_data(user_data)

    rows = []
    free_left = free_spins_left(user)
    if free_left > 0:
        rows.append([InlineKeyboardButton(
            text=get_text(user, "free", left=free_left, total=free_spins_allowed(user)),
            callback_data="spin_free", style="success")])
    rows.append([InlineKeyboardButton(text=get_text(user, "spin_more", price=price_label("spin_paid_20", user)), callback_data="spin_paid", style="success")])
    rows.append([InlineKeyboardButton(text=get_text(user, "back"), callback_data="spin_back", style="danger")])
    keyboard = InlineKeyboardMarkup(inline_keyboard=rows)

    mode_text = get_text(user, "spin_mode_free" if free else "spin_mode_paid")
    await bot.send_message(
        chat_id,
        get_text(user, "spin_result_header", result=result_text, mode=mode_text),
        reply_markup=keyboard,
        parse_mode="Markdown"
    )


