def spend_bucks(user, price):
    if user.get("bucks", 0) < price:
        return False
    user["bucks"] -= price
    return True


async def grant_gift_xp(chat_id, user, amount):
    """Такая же проверка уровня близости, что и в handle_message при обычном сообщении —
    вынесена отдельно, чтобы не трогать стабильный основной хендлер ради ещё одного источника XP."""
    user["xp"] = max(0, user.get("xp", 0) + amount)
    new_level = get_intimacy_level(user)
    old_level = user.get("last_level", 0)
    if new_level != old_level:
        user["last_level"] = new_level
        if new_level >= INTIM_LEVEL_REWARD and not user.get("intim_scene_unlocked"):
            user["intim_scene_unlocked"] = True
        if new_level > old_level:
            congrats = get_level_congratulation(user, new_level)
            if congrats:
                await app_notify(chat_id, user, congrats, reply_markup=get_full_kb(user))
            if new_level == INTIM_LEVEL_REWARD:
                await app_notify(chat_id, user, get_text(user, "intim_free_level"), reply_markup=get_full_kb(user))
    save_data(user_data)


def gift_effective_item(item, user):
    """Для аксессуаров с male_variant подменяет вид/название под персонажа-мужчину (часы вместо
    каблуков и т.п.) — цена и эффекты (satiety/mood/xp) всегда берутся из базового item, вариант
    переопределяет только emoji/ru/en/de/reaction_hint."""
    variant = item.get("male_variant")
    if variant and user.get("gender") == "male":
        return {**item, **variant}
    return item


def gift_option_label(key, user):
    item = gift_effective_item(GIFT_ITEMS[key], user)
    lang = user.get("lang", "ru")
    label = item.get(lang, item["ru"])
    return f"{item['emoji']} {label}"


def medicine_option_label(key, user):
    item = MEDICINE_ITEMS[key]
    lang = user.get("lang", "ru")
    label = item.get(lang, item["ru"])
    return f"{item['emoji']} {label}"


def item_cooldown_key(category, key):
    return f"{category}:{key}"


def item_ready_at(user, category, key, item):
    """None, если товар уже можно купить/подарить, иначе — datetime, когда можно будет снова.
    Единый механизм и для еды (минуты), и для подарков (часы/дни) — раньше подарки-аксессуары
    были заблокированы НАВСЕГДА после первой покупки (repeatable=False), а еда вообще не
    ограничивалась; по фидбэку это заменено на интервал у каждого предмета свой (cooldown_minutes),
    чтобы нельзя было закормить/задарить одним и тем же раз в секунду, но и не блокировать вещь
    насовсем — большой подарок вроде телефона снова доступен, просто не сразу."""
    cooldown = item.get("cooldown_minutes")
    if not cooldown:
        return None
    last = user.get("item_cooldowns", {}).get(item_cooldown_key(category, key))
    if not last:
        return None
    try:
        ready_at = datetime.fromisoformat(last) + timedelta(minutes=cooldown)
    except (ValueError, TypeError):
        return None
    return ready_at if datetime.now() < ready_at else None


def mark_item_purchased(user, category, key):
    user.setdefault("item_cooldowns", {})[item_cooldown_key(category, key)] = datetime.now().isoformat()


def cooldown_phrase(user, ready_at):
    """Компактная человекочитаемая строка вида '2 ч'/'45 мин'/'3 дн' до момента ready_at."""
    seconds = max(1, (ready_at - datetime.now()).total_seconds())
    minutes = seconds / 60
    if minutes < 60:
        return get_text(user, "cd_min", n=max(1, round(minutes)))
    hours = minutes / 60
    if hours < 24:
        return get_text(user, "cd_hours", n=max(1, round(hours)))
    days = hours / 24
    return get_text(user, "cd_days", n=max(1, round(days)))


def format_item_effects(item, user):
    parts = []
    if item.get("full_restore"):
        parts.append(get_text(user, "effect_satiety_full"))
        parts.append(get_text(user, "effect_mood_full"))
        parts.append(get_text(user, "effect_water_full"))
    else:
        if item.get("satiety"):
            parts.append(get_text(user, "effect_satiety", n=item["satiety"]))
        if item.get("mood"):
            parts.append(get_text(user, "effect_mood", n=item["mood"]))
        if item.get("water"):
            parts.append(get_text(user, "effect_water", n=item["water"]))
    if item.get("xp"):
        parts.append(get_text(user, "effect_xp", n=item["xp"]))
    return ", ".join(parts)


def apply_shop_item_effects(user, item):
    if item.get("full_restore"):
        user["satiety"] = SATIETY_MAX
        user["mood"] = MOOD_MAX
        user["water"] = WATER_MAX
        user["water_zero_since"] = None
        user["dehydration_warned"] = False
        user["dehydration_urgent_warned"] = False
    else:
        if "satiety" in item:
            user["satiety"] = min(SATIETY_MAX, user.get("satiety", SATIETY_MAX) + item["satiety"])
        if "mood" in item:
            user["mood"] = min(MOOD_MAX, max(-MOOD_MAX, user.get("mood", 0) + item["mood"]))
        if "water" in item:
            user["water"] = min(WATER_MAX, user.get("water", WATER_MAX) + item["water"])
            if user["water"] > 0:
                user["water_zero_since"] = None
                user["dehydration_warned"] = False
                user["dehydration_urgent_warned"] = False
    if item.get("tipsy_minutes"):
        user["tipsy_until"] = (datetime.now() + timedelta(minutes=item["tipsy_minutes"])).isoformat()
        user["tipsy_level"] = item.get("tipsy_level", "light")


SHOP_CATEGORY_ORDER = ["food", "gift", "date"]
SHOP_CATEGORY_TEXT_KEY = {"food": "shop_category_food", "gift": "shop_category_gift", "date": "shop_category_date"}

# Каталог аксессуаров конечен и одноразовый — рано или поздно всё куплено. "Свой подарок" даёт
# запасной вариант: любой текст, который ещё не дарили (дубли по нормализованному тексту), с
# рандомным настроением из диапазона обычных аксессуаров (см. их mood выше — 18..45), а не
# средним: со случайным числом каждый раз приятнее, чем одна и та же предсказуемая цифра.
CUSTOM_GIFT_PRICE = 7500
CUSTOM_GIFT_MOOD_RANGE = (18, 45)
CUSTOM_GIFT_MAX_LEN = 60


# Подарки и свидания открываются по уровню близости: иначе магазин + работа заменяли бы переписку
# (купил кольцо на первом же уровне -- и общаться незачем). Близость растёт от общения, а не от баксов.
GIFT_MIN_LEVEL = {
    "sweets": 1, "flowers": 1, "perfume": 2, "cosmetics": 2, "heels": 3, "concert": 3, "theater": 3,
    "dress": 4, "date": 4, "jewelry": 5, "serenade": 5, "phone": 6, "sea_trip": 6,
    "ring": 8, "paris": 8, "car": 9, "star": 10,
}
CUSTOM_GIFT_MIN_LEVEL = 4


def gift_locked_level(user, key):
    """Нужный уровень, если подарок ещё закрыт, иначе None."""
    need = GIFT_MIN_LEVEL.get(key, 1)
    return need if get_intimacy_level(user) < need else None


def gift_locked_text(user, level):
    return get_text(user, "gift_locked_alert", level=level)


def apply_custom_gift(user, gift_text):
    """Общая проверка+списание для чатового ввода (writing_custom_gift) и для Shop Mini App
    (см. api_custom_gift_handler) — применяет эффекты и возвращает (ok, error_text, custom_item).
    error_text уже локализован через get_text, custom_item отдаётся только при ok=True."""
    if user.get("illness"):
        return False, get_text(user, "gift_blocked_illness"), None
    if get_intimacy_level(user) < CUSTOM_GIFT_MIN_LEVEL:
        return False, gift_locked_text(user, CUSTOM_GIFT_MIN_LEVEL), None
    gift_text = (gift_text or "").strip()
    if not gift_text or len(gift_text) > CUSTOM_GIFT_MAX_LEN:
        return False, get_text(user, "custom_gift_invalid", n=CUSTOM_GIFT_MAX_LEN), None
    normalized = gift_text.lower()
    if normalized in user.get("custom_gifts_given", []):
        return False, get_text(user, "custom_gift_duplicate"), None
    if not spend_bucks(user, CUSTOM_GIFT_PRICE):
        return False, get_text(user, "not_enough_bucks", n=CUSTOM_GIFT_PRICE - user.get("bucks", 0)), None
    mood = random.randint(*CUSTOM_GIFT_MOOD_RANGE)
    xp = round(mood * 0.6)
    custom_item = {
        "ru": gift_text, "en": gift_text, "de": gift_text, "emoji": "🎁", "mood": mood, "xp": xp,
        "reaction_hint": ("Это подарок, который собеседник придумал сам, специально для тебя — не "
                          "что-то из готового списка. Благодарность самая искренняя и трогательная "
                          "из всех: чувствуется, что он(а) думал(а) именно о тебе."),
    }
    apply_shop_item_effects(user, custom_item)
    user.setdefault("custom_gifts_given", []).append(normalized)
    save_data(user_data)
    return True, None, custom_item

# Личная подпись к обычному (каталожному) подарку/еде — в отличие от custom-подарка это не
# отдельный предмет со своей ценой, а просто пара слов от пользователя поверх штатной покупки,
# см. execute_item_purchase/generate_shop_reaction.
ITEM_NOTE_MAX_LEN = 150


# Акции дня: товар дня (-30%) и ещё по одному подарку и еде (-15%) -- повод заглядывать в магазин и
# тратить баксы (по фидбэку «баксы копятся, и на них всё равно»). Скидки настоящие: цена за баксы
# реально ниже, это ничего не стоит (баксы виртуальные). На товары за звёзды скидок нет -- там
# только честная «выгода» пачек (см. energizer_pack_saving). Выбор по дате -- одинаков для всех.
DEAL_DISCOUNT = 0.3
PROMO_DISCOUNT = 0.15


def promo_of_day():
    """{(category, key): скидка} на сегодня."""
    rnd = random.Random(local_today().toordinal())
    gifts = sorted(GIFT_ITEMS)
    deal = gifts[local_today().toordinal() % len(gifts)]
    second = rnd.choice([k for k in gifts if k != deal])
    food = rnd.choice(sorted(k for k, it in FOOD_ITEMS.items() if it["price"] >= 500))
    return {("gift", deal): DEAL_DISCOUNT, ("gift", second): PROMO_DISCOUNT, ("food", food): PROMO_DISCOUNT}


def deal_of_day_key():
    return next(k for (cat, k), d in promo_of_day().items() if cat == "gift" and d == DEAL_DISCOUNT)


def promo_discount(category, key):
    return promo_of_day().get((category, key), 0)


def item_price(user, category, key, item):
    discount = promo_discount(category, key)
    if discount:
        return int(round(item["price"] * (1 - discount) / 25.0)) * 25
    return item["price"]


def promo_banner_text(user):
    """Короткая строка «акции дня» -- только в шапке магазина, не рассылкой."""
    lang = user.get("lang", "ru")
    parts = []
    for (cat, key), discount in promo_of_day().items():
        item = (GIFT_ITEMS if cat == "gift" else FOOD_ITEMS)[key]
        shown = gift_effective_item(item, user) if cat == "gift" else item
        parts.append(f"{shown['emoji']} {shown.get(lang, shown['ru'])} −{int(discount * 100)}%")
    if spin_sale_active():
        parts.insert(0, get_text(user, "spin_sale_part", sale=SPIN_SALE_STARS, regular=SPIN_LIST_STARS))
    if energizer_sale_active():
        parts.insert(0, get_text(user, "energizer_sale_part", n=energizer_sale_percent()))
    if sub_sale_active():
        parts.insert(0, get_text(user, "sub_sale_part", n=int(SUB_SALE_DISCOUNT * 100)))
    return ", ".join(parts)


def promo_max_percent(user):
    """Самая большая скидка сегодня -- для бирки «Скидки до N%» в шапке магазина."""
    values = [d for d in promo_of_day().values()] + [energizer_discount_today()]
    if spin_sale_active():
        values.append(1 - SPIN_SALE_STARS / SPIN_LIST_STARS)
    if sub_sale_active():
        values.append(SUB_SALE_DISCOUNT)
    if coupon_active(user):
        values.append(user["coupon"]["discount"])
    return int(round(max(values) * 100))


# Распродажи по календарю: в какой день какая скидка -- случайно, но детерминированно по дате (одинаково
# у всех и не меняется в течение дня). Скидки настоящие: в дни без распродажи действует обычная цена.
def _day_rng(tag):
    return random.Random(f"{tag}-{local_today().isoformat()}")


# Энергетики: обычная цена ENERGIZER_LIST_STARS; примерно в 3 днях из 5 -- скидка 15/20/28%.
ENERGIZER_LIST_STARS = {"energizer_2": 25, "energizer_6": 69, "energizer_15": 165, "energizer_35": 359}
ENERGIZER_SALE_OPTIONS = [0, 0, 0.15, 0.2, 0.28]


def energizer_discount_today():
    return _day_rng("energizer").choice(ENERGIZER_SALE_OPTIONS)


def energizer_sale_active():
    return energizer_discount_today() > 0


def energizer_stars(key):
    return max(1, int(round(ENERGIZER_LIST_STARS[key] * (1 - energizer_discount_today()))))


def energizer_sale_percent():
    return int(round(energizer_discount_today() * 100))


# Прежние цены, которые реально были у товаров (показываем зачёркнутыми рядом с текущей).
PREVIOUS_STARS = {"intim_scene": 45, "wake_now": 50, "defibrillator": 55}
SPIN_LIST_STARS = 15  # обычная цена платного прокрута
SPIN_SALE_STARS = 10  # примерно в 2 днях из 5 -- распродажа
SPIN_SALE_CHANCE = 0.4


def strike(text):
    """Зачёркнутый текст для кнопок Telegram (там нет разметки) -- через комбинирующий символ U+0336."""
    return "".join(ch + "\u0336" for ch in str(text))


def spin_sale_active():
    return _day_rng("spin").random() < SPIN_SALE_CHANCE


def spin_stars():
    return SPIN_SALE_STARS if spin_sale_active() else SPIN_LIST_STARS


# Распродажа подписок на выходных: SUPER PRO и ELITE реально дешевле только в пт-вс.
SUB_SALE_WEEKDAYS = {4, 5, 6}
SUB_SALE_DISCOUNT = 0.2
SUB_SALE_PRODUCTS = {"subscribe_super", "subscribe_elite"}
# Бонус за первую покупку: скидка на следующую покупку за звёзды, на ограниченное время.
FIRST_BUY_COUPON = 0.15
FIRST_BUY_COUPON_HOURS = 72


def sub_sale_active():
    return local_today().weekday() in SUB_SALE_WEEKDAYS


def coupon_active(user):
    coupon = (user or {}).get("coupon")
    if not coupon:
        return False
    try:
        return datetime.now() < datetime.fromisoformat(coupon["until"])
    except (KeyError, ValueError, TypeError):
        return False


def regular_stars(payload):
    """Обычная цена без персональных скидок (с учётом будней/выходных у энергетиков и прокрута)."""
    if payload in ENERGIZER_PACKS:
        return energizer_stars(payload)
    if payload in ("spin_paid_20", "spin_paid_webapp"):
        return spin_stars()
    return PRODUCTS[payload]["stars"]


def product_discount(payload, user=None):
    discount = SUB_SALE_DISCOUNT if payload in SUB_SALE_PRODUCTS and sub_sale_active() else 0
    if coupon_active(user):
        discount = max(discount, user["coupon"]["discount"])
    return discount


def product_stars(payload, user=None):
    """Цена товара в звёздах для этого пользователя сейчас -- одна точка правды для счетов и подписей."""
    base = regular_stars(payload)
    discount = product_discount(payload, user)
    return max(1, int(round(base * (1 - discount)))) if discount else base


def price_label(payload, user=None):
    """«4̶5̶ 30» -- если есть настоящая прежняя/обычная цена выше текущей, иначе просто цена."""
    now = product_stars(payload, user)
    ref = regular_stars(payload)
    if payload in ENERGIZER_PACKS:
        ref = ENERGIZER_LIST_STARS[payload]
    elif payload in ("spin_paid_20", "spin_paid_webapp"):
        ref = SPIN_LIST_STARS
    if payload in PREVIOUS_STARS:
        ref = max(ref, PREVIOUS_STARS[payload])
    return f"{strike(ref)} {now}" if now < ref else str(now)


def coupon_note(user):
    """Подпись «персональная скидка за первую покупку» рядом с ценами, пока купон действует, иначе None."""
    if not coupon_active(user):
        return None
    left = max(1, round((datetime.fromisoformat(user["coupon"]["until"]) - datetime.now()).total_seconds() / 3600))
    return get_text(user, "coupon_note", n=int(user["coupon"]["discount"] * 100), hours=left)


def sales_lines(user):
    """Строки об актуальных распродажах и купоне -- для меню подписок."""
    lines = []
    if sub_sale_active():
        lines.append(get_text(user, "sub_sale_line", n=int(SUB_SALE_DISCOUNT * 100)))
    if coupon_active(user):
        left = max(1, round((datetime.fromisoformat(user["coupon"]["until"]) - datetime.now()).total_seconds() / 3600))
        lines.append(get_text(user, "coupon_line", n=int(user["coupon"]["discount"] * 100), hours=left))
    return lines


def energizer_pack_saving(key, user=None):
    """Честная выгода: насколько штука в этой пачке сейчас дешевле обычной цены штуки в самой маленькой
    пачке (пн-чт, ENERGIZER_LIST_STARS) -- учитывает и размер пачки, и распродажу выходных, и купон."""
    base = ENERGIZER_LIST_STARS["energizer_2"] / ENERGIZER_PACKS["energizer_2"]["amount"]
    now = product_stars(key, user) / ENERGIZER_PACKS[key]["amount"]
    return max(0, int(round((1 - now / base) * 100)))


def get_shop_kb(user):
    """Один товар — один ряд на всю ширину: раньше в паре с этой кнопкой была ещё и ✍️ для
    записки, из-за чего у каждой кнопки оставалась едва половина ширины и текст (вместе с ценой)
    обрезался Телеграмом. Подарок/еда с запиской теперь отдельный экран — см. get_shop_note_kb."""
    entries = [(key, item, f"shop_food_{key}", False) for key, item in FOOD_ITEMS.items()]
    entries += [(key, item, f"shop_gift_{key}", True) for key, item in GIFT_ITEMS.items()]

    rows = []
    # Лекарства — только пока персонаж реально болен (см. ILLNESSES), сверху, до остальных
    # категорий: это самое срочное, что вообще может понадобиться в магазине сейчас.
    if user.get("illness"):
        rows.append([InlineKeyboardButton(text=get_text(user, "shop_category_medicine"), callback_data="shop_noop")])
        dose_at = medicine_next_dose_at(user)
        for key, item in MEDICINE_ITEMS.items():
            price_part = f"⏳{cooldown_phrase(user, dose_at)}" if dose_at else f"{item['price']}💵"
            rows.append([InlineKeyboardButton(text=f"{medicine_option_label(key, user)} — {price_part}",
                                              callback_data=f"shop_medicine_{key}", style="success")])
    for category in SHOP_CATEGORY_ORDER:
        cat_entries = [e for e in entries if e[1].get("category") == category]
        if not cat_entries:
            continue
        rows.append([InlineKeyboardButton(text=get_text(user, SHOP_CATEGORY_TEXT_KEY[category]), callback_data="shop_noop")])
        for key, item, callback_data, is_gift in cat_entries:
            if is_gift:
                label = gift_option_label(key, user)
            else:
                label = intim_option_label(FOOD_ITEMS, key, user)
            ready_at = item_ready_at(user, "gift" if is_gift else "food", key, item)
            price = item_price(user, "gift" if is_gift else "food", key, item)
            deal = "🔥 " if promo_discount("gift" if is_gift else "food", key) else ""
            locked = gift_locked_level(user, key) if is_gift else None
            suffix = f" — ⏳{cooldown_phrase(user, ready_at)}" if ready_at else f" — {price}💵"
            if is_gift and user.get("illness"):
                deal, suffix = "🤒 ", " — " + get_text(user, "gift_sick_short")
            elif locked:
                deal, suffix = "🔒 ", " — " + get_text(user, "gift_locked_short", level=locked)
            rows.append([InlineKeyboardButton(text=f"{deal}{label}{suffix}", callback_data=callback_data, style="success")])
        # ВАЖНО: было "category = ..." внутри цикла выше — это затирало переменную внешнего
        # цикла (SHOP_CATEGORY_ORDER: food/treat/accessory), из-за чего проверка ниже никогда
        # не срабатывала и кнопка "Свой подарок" молча пропадала из магазина. Убрано.
        if category == "gift":
            rows.append([InlineKeyboardButton(
                text=get_text(user, "custom_gift_btn", price=CUSTOM_GIFT_PRICE),
                callback_data="shop_custom_gift_start", style="success")])

    rows.append([InlineKeyboardButton(text=gt(user, "shop_cat_games"), callback_data="shop_noop")])
    for key, offer in GAME_OFFERS.items():
        rows.append([InlineKeyboardButton(text=f"{offer['emoji']} {game_offer_name(user, key)} — {game_price_label(user, key)}",
                                          callback_data=f"game_{key}", style="success")])
    if WEBAPP_URL:
        rows.append([InlineKeyboardButton(text=gt(user, "play_strip_btn"), web_app=WebAppInfo(url=f"{WEBAPP_URL}/play?game=strip"),
                                          style="success")])
    rows.append([InlineKeyboardButton(text=gt(user, "shop_cat_exchange"), callback_data="shop_noop")])
    ex_key = exchange_today()
    ex_offer = BUCKS_EXCHANGE[ex_key]
    ex_label = f" — {ex_offer['price']}💵" if exchange_left(user, ex_key) else " — " + gt(user, "ex_bought_today")
    rows.append([InlineKeyboardButton(text=f"{ex_offer['emoji']} {exchange_name(user, ex_key)}{ex_label}",
                                      callback_data=f"shop_ex_{ex_key}", style="success")])
    rows.append([InlineKeyboardButton(text=get_text(user, "shop_note_menu_btn"), callback_data="shop_note_menu", style="success")])
    rows.append([InlineKeyboardButton(text=get_text(user, "back_to_profile"), callback_data="back_to_profile", style="danger")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def get_shop_note_kb(user):
    """Тот же каталог, что в get_shop_kb, но кнопки ведут в написание личного сообщения (см.
    shop_item_note_start) вместо мгновенной покупки — отдельный экран, чтобы основной список
    магазина оставался в один столбец и не обрезался (см. get_shop_kb)."""
    entries = [(key, item, f"note_food_{key}", False) for key, item in FOOD_ITEMS.items()]
    entries += [(key, item, f"note_gift_{key}", True) for key, item in GIFT_ITEMS.items()]

    rows = []
    for category in SHOP_CATEGORY_ORDER:
        cat_entries = [e for e in entries if e[1].get("category") == category]
        if not cat_entries:
            continue
        rows.append([InlineKeyboardButton(text=get_text(user, SHOP_CATEGORY_TEXT_KEY[category]), callback_data="shop_noop")])
        for key, item, callback_data, is_gift in cat_entries:
            if is_gift:
                label = gift_option_label(key, user)
            else:
                label = intim_option_label(FOOD_ITEMS, key, user)
            ready_at = item_ready_at(user, "gift" if is_gift else "food", key, item)
            price = item_price(user, "gift" if is_gift else "food", key, item)
            deal = "🔥 " if promo_discount("gift" if is_gift else "food", key) else ""
            locked = gift_locked_level(user, key) if is_gift else None
            suffix = f" — ⏳{cooldown_phrase(user, ready_at)}" if ready_at else f" — {price}💵"
            if is_gift and user.get("illness"):
                deal, suffix = "🤒 ", " — " + get_text(user, "gift_sick_short")
            elif locked:
                deal, suffix = "🔒 ", " — " + get_text(user, "gift_locked_short", level=locked)
            rows.append([InlineKeyboardButton(text=f"{deal}{label}{suffix}", callback_data=callback_data, style="success")])

    rows.append([InlineKeyboardButton(text=get_text(user, "back"), callback_data="profile_shop", style="danger")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@dp.callback_query(lambda c: c.data == "shop_note_menu")
async def shop_note_menu(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    await call.message.answer(get_text(user, "shop_note_title", bucks=user.get("bucks", 0)),
                              reply_markup=get_shop_note_kb(user), parse_mode="Markdown")
    await call.answer()


@dp.callback_query(lambda c: c.data == "shop_custom_gift_start")
async def shop_custom_gift_start(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    user["writing_custom_gift"] = True
    save_data(user_data)
