async def use_defib_stock_cb(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    if not user.get("dead") or user.get("defib_stock", 0) <= 0:
        await call.answer()
        return
    user["defib_stock"] -= 1
    user["dead"] = False
