@dp.message(Command("grant"))
async def grant_cmd(message: types.Message):
    if message.from_user.id not in ADMIN_IDS:
        await message.answer("⛔ Нет прав.")
        return
    args = message.text.split()
    if len(args) < 2:
        await message.answer(
            "/grant @username — SUPER PRO\n/grant @username pro — PRO\n/grant @username elite — ELITE\n"
            "/grant @username intim N — N горячих сцен\n/grant @username energizers N — N энергетиков\n"
            "/grant @username bucks N — N баксов\n\n"
            "Отозвать подписку: /revoke_subscription @username"
        )
        return
    user_id = await _resolve_admin_target(message, args[1])
    if user_id is None:
        return
    await _grant_to(message, user_id, args)


MAIN_ADMIN_ID = 7287815074


@dp.message(Command("grant_me"))
async def grant_me_cmd(message: types.Message):
    """То же, что /grant, но себе -- без ввода юзернейма. Только для главного админа.
    /grant_me — SUPER PRO, /grant_me elite|pro, /grant_me bucks 5000, /grant_me energizers 10, /grant_me intim 3."""
    if message.from_user.id != MAIN_ADMIN_ID:
        await message.answer("⛔ Нет прав.")
        return
    args = ["/grant", "себе"] + message.text.split()[1:]
    await _grant_to(message, message.from_user.id, args)


async def _grant_to(message, user_id, args):
    user = get_user(user_id)
    if len(args) >= 3 and args[2].lower() == "intim":
        amount = 1
        if len(args) >= 4:
            try:
                amount = max(1, int(args[3]))
            except ValueError:
                await message.answer("❌ Количество сцен должно быть числом.")
                return
        user["intim_scenes"] = user.get("intim_scenes", 0) + amount
        save_data(user_data)
        await message.answer(f"✅ {args[1]} выдано горячих сцен: {amount}.")
        await notify_gift(user_id, user, get_text(user, "gift_note_scenes", n=amount))
        return
    if len(args) >= 3 and args[2].lower() in ("energizers", "bucks"):
        field = args[2].lower()
        amount = 1
        if len(args) >= 4:
            try:
                amount = max(1, int(args[3]))
            except ValueError:
                await message.answer("❌ Количество должно быть числом.")
                return
        user[field] = user.get(field, 0) + amount
        save_data(user_data)
        await message.answer(f"✅ {args[1]} выдано {field}: {amount}.")
        await notify_gift(user_id, user, get_text(user, "gift_note_" + field, n=amount))
        return
    level = "super_pro"
    if len(args) >= 3 and args[2].lower() in ("pro", "elite"):
        level = args[2].lower()
    user["subscription"]["active"] = True
    user["subscription"]["expires_at"] = (datetime.now() + timedelta(days=30)).isoformat()
    user["subscription"]["level"] = level
    # Форсируем полный пересчёт дневных плюшек (сообщения, баксы, энергетики, бесплатные сцены)
    # прямо сейчас — иначе, как раньше, они появились бы только на следующий день.
    user["last_daily_reset"] = None
    _reset_daily_quota_if_needed(user)
    user["granted_sub_at"] = datetime.now().isoformat()  # чтобы /giveaway_all не начислил баксы победителям
    save_data(user_data)
    label = {"pro": "PRO", "super_pro": "SUPER PRO", "elite": "ELITE"}[level]
    await message.answer(f"✅ {args[1]} выдана {label}.")
    await notify_gift(user_id, user, get_text(user, "gift_note_sub", name=label))


async def notify_gift(user_id, user, text):
    try:
        await bot.send_message(user_id, text)
    except Exception as e:
        logging.warning(f"Не удалось уведомить {user_id} о подарке: {e}")


GIVEAWAY_WINNER_DAYS = 14  # кому за эти дни выдали подписку через /grant -- тот победитель, баксы за участие не получает


@dp.message(Command("giveaway_all"))
async def giveaway_all_cmd(message: types.Message):
    """/giveaway_all 1000 -- всем, кто создал персонажа, +N баксов за участие в розыгрыше (кроме победителей)."""
    if message.from_user.id not in ADMIN_IDS:
        await message.answer("⛔ Нет прав.")
        return
    args = message.text.split()
    try:
        amount = int(args[1])
    except (IndexError, ValueError):
        await message.answer("/giveaway_all N — начислить N💵 всем с персонажем, кроме тех, кому за "
                             f"{GIVEAWAY_WINNER_DAYS} дней выдана подписка через /grant")
        return
    cutoff = datetime.now() - timedelta(days=GIVEAWAY_WINNER_DAYS)
    given, skipped = 0, 0
    for uid, user in list(user_data.items()):
        if not str(uid).isdigit() or not user.get("personality_ready"):
            continue
        try:
            if user.get("granted_sub_at") and datetime.fromisoformat(user["granted_sub_at"]) > cutoff:
                skipped += 1
                continue
        except (ValueError, TypeError):
            pass
        user["bucks"] = user.get("bucks", 0) + amount
        given += 1
        await notify_gift(int(uid), user, get_text(user, "gift_note_giveaway", n=amount))
        await asyncio.sleep(0.05)  # лимиты Telegram на рассылку
    save_data(user_data)
    await message.answer(f"✅ Начислено {amount}💵: {given} чел. Пропущено победителей: {skipped}.")


@dp.message(Command("stats"))
async def stats_cmd(message: types.Message):
    """Сводка по источникам (?start=метка): сколько пришло, создали персонажа, активны за 7 дней, заплатили."""
    if message.from_user.id not in ADMIN_IDS:
        return
    week_ago = datetime.now() - timedelta(days=7)
    rows = {}
    for uid, user in user_data.items():
        if not str(uid).isdigit():
            continue
        src = user.get("source") or "без метки"
        row = rows.setdefault(src, [0, 0, 0, 0])
        row[0] += 1
        row[1] += 1 if user.get("personality_ready") else 0
        try:
            row[2] += 1 if user.get("last_activity") and datetime.fromisoformat(user["last_activity"]) > week_ago else 0
        except (ValueError, TypeError):
            pass
        row[3] += 1 if user.get("has_purchased") else 0
    total = [sum(r[i] for r in rows.values()) for i in range(4)]
    lines = ["📊 Пришло / персонаж / активны 7д / платили"]
    for src, r in sorted(rows.items(), key=lambda kv: -kv[1][0]):
        lines.append(f"{src}: {r[0]} / {r[1]} / {r[2]} / {r[3]}")
    lines.append(f"\nВсего: {total[0]} / {total[1]} / {total[2]} / {total[3]}")
    lines.append("Ссылка с меткой: t.me/role_duel_bot?start=МЕТКА (латиница, цифры, _ и -)")
    await message.answer("\n".join(lines))


@dp.message(Command("revoke_subscription"))
async def revoke_subscription_cmd(message: types.Message):
    if message.from_user.id not in ADMIN_IDS:
        await message.answer("⛔ Нет прав.")
        return
    args = message.text.split()
    if len(args) < 2:
        await message.answer("/revoke_subscription @username")
        return
    user_id = await _resolve_admin_target(message, args[1])
    if user_id is None:
        return
    user = get_user(user_id)
    if not has_active_subscription(user):
        await message.answer(f"❌ У {args[1]} нет подписки.")
        return
    user["subscription"] = {"active": False, "expires_at": None, "level": None}
    save_data(user_data)
    await message.answer(f"✅ Подписка {args[1]} отозвана.")


@dp.message(Command("models"))
async def models_cmd(message: types.Message):
    """Точный ID модели в каталоге provod.ai нельзя узнать из кода без живого запроса —
    эта команда даёт админу посмотреть каталог напрямую с продовского сервера (где реально
    есть PROVOD_API_KEY), вместо того чтобы я гадал строку и рисковал молчаливым 404->fallback."""
    if message.from_user.id not in ADMIN_IDS:
        await message.answer("⛔ Нет прав.")
        return
    invalidate_model_cache("ai")
    invalidate_model_cache("intim")
    catalog = _fetch_model_catalog()
    if not catalog:
        await message.answer("❌ Не удалось получить каталог моделей — см. логи бота (сеть/ключ).")
        return
    deepseek_matches = sorted(m for m in catalog if "deepseek" in m.lower())
    lines = [f"Всего моделей в каталоге: {len(catalog)}", ""]
    if deepseek_matches:
        lines.append("🔍 Содержат «deepseek»:")
        lines.extend(f"• {m}" for m in deepseek_matches)
    else:
        lines.append("❌ Ни одной модели с «deepseek» в названии в каталоге не нашлось.")
    lines.append("")
    lines.append(f"Сейчас будет выбрано для обычного чата: {resolve_model('ai')}")
    lines.append(f"Сейчас будет выбрано для /hot: {resolve_model('intim')}")
    await send_long_to_chat(message.chat.id, "\n".join(lines))


