@dp.callback_query(lambda c: c.data.startswith("intim_type_"))
async def choose_intim_type(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    scene_type = call.data[len("intim_type_"):]
    if scene_type not in INTIM_SCENES:
        await call.answer()
        return
    await safe_delete(call.message)
    await bot.send_message(call.message.chat.id, get_text(user, "intim_choose_location"),
                           reply_markup=get_intim_locations_kb(user, scene_type))
    await call.answer()


@dp.callback_query(lambda c: c.data.startswith("intim_loc_"))
async def choose_intim_location(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    scene_type, _, location = call.data[len("intim_loc_"):].partition(":")
    if scene_type not in INTIM_SCENES or location not in intim_compatible_locations(scene_type):
        await call.answer()
        return
    await safe_delete(call.message)
    await bot.send_message(call.message.chat.id, get_text(user, "intim_choose_dominant"),
                           reply_markup=get_intim_dominant_kb(user, scene_type, location))
    await call.answer()


@dp.callback_query(lambda c: c.data.startswith("intim_dom_"))
async def choose_intim_dominant(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    scene_type, location, dominant = call.data[len("intim_dom_"):].split(":", 2)
    if scene_type not in INTIM_SCENES or location not in INTIM_LOCATIONS or dominant not in INTIM_DOMINANTS:
        await call.answer()
        return

    kind = consume_intim_scene(user)
    if kind is None:
        await safe_delete(call.message)
        await bot.send_message(call.message.chat.id, get_text(user, "intim_none"),
                               reply_markup=get_intim_buy_kb(user))
        await call.answer()
        return

    await safe_delete(call.message)
    if kind == "level":
        await bot.send_message(call.message.chat.id, get_text(user, "intim_free_level"))
    elif kind == "subscription":
        await bot.send_message(call.message.chat.id, get_text(user, "intim_free_sub"))
    await call.answer()

    ok = await generate_intim_scene(call, user, scene_type, location=location, dominant=dominant, free=kind != "paid")
    if not ok:
        # сцену не показали — возвращаем ровно то, что списали
        refund_intim_scene(user, kind)


def refund_intim_scene(user, kind):
    if kind == "level":
        user["intim_scene_used"] = False
    elif kind == "subscription":
        field = free_intim_field(user)
        if field:
            user[field] = user.get(field, 0) + 1
    else:
        user["intim_scenes"] = user.get("intim_scenes", 0) + 1
    save_data(user_data)


def build_intim_prompt(user, scene_type, location, dominant="any", arc_position=1, arc_length=INTIM_ARC_LENGTH):
    """Отдельный промпт для интим-сцен — НЕ через build_prompt(). Там SAFE/ADULT правило переключается
    по обычному стилю чата (а не по праву на интим-сцену), плюс сдержанность по уровню близости и
    медленный темп сближения — это заставляло ИИ уходить от темы вместо прямого показа выбранной сцены.
    Здесь только личность персонажа, безусловный ADULT_CONTENT_RULE и сама сцена. scene_type
    здесь уже конкретный (random разрешается в generate_intim_scene ДО вызова) — иначе
    "продолжение" сцены каждый раз перевыбирало бы случайный тип заново.
    arc_position/arc_length — см. INTIM_ARC_LENGTH: растягивают развязку на несколько покупок
    подряд вместо одной сцены с мгновенным финалом (по фидбэку: хотелось бы оставить
    предвкушение и повод вернуться, а не выдавать всё сразу)."""
    scene = INTIM_SCENES[scene_type]
    place = INTIM_LOCATIONS[location]
    dominant_rule = INTIM_DOMINANTS.get(dominant, INTIM_DOMINANTS["any"])["prompt"]

    if user.get("custom_character"):
        # Для своего персонажа НЕ запрещаем называть себя по имени (в отличие от пресетных
        # персон ниже) — иначе прямой конфликт с "Ты — Бэтмен" даёт обезличенный результат:
        # модель не может опереться на единственный явный сигнал личности, который у неё есть.
        identity = (
            f"Ты — {user['custom_character']}. Полностью вживись в эту личность и её характер: если "
            f"персонаж узнаваем, веди себя как он — с его характерными чертами и манерой речи, а не "
            f"обезличенно. Можешь называть себя по имени, когда это естественно по ходу разговора.\n"
        )
        style_flavor = ""
        name_ban = (
            "Ты НИКОГДА не спрашиваешь имя собеседника и не используешь его имя, даже если оно было "
            "названо. Обращайся к собеседнику ТОЛЬКО на «ты» — даже если в той же фразе упомянут предмет "
            "(окно, чашка и т.п.), взгляд или действие в сторону самого собеседника называй "
            "«тебя/тебе», а НЕ «него/неё» (пример ошибки: «перевожу взгляд с окна на него» — "
            "правильно «...на тебя»).\n"
        )
    else:
        world_desc = WORLDS[user["world"]]
        gender_info = GENDERS[user["gender"]]
        style_key = get_display_style(user)
        style_desc = STYLES[style_key]["description"]
        identity = (
            f"Ты — {gender_info['name']}, тебе {gender_info['age']} лет. Ты живёшь в {world_desc} "
            f"{style_desc}\n"
        )
        style_flavor = STYLE_INTIM_FLAVOR.get(style_key, "")
        name_ban = (
            "**ВАЖНЕЙШЕЕ ПРАВИЛО:** Ты НИКОГДА не называешь себя по имени, не представляешься, не говоришь "
            "«меня зовут», не используешь своё имя. Ты также НИКОГДА не спрашиваешь имя собеседника и не "
            "используешь его имя, даже если оно было названо. Обращайся к собеседнику ТОЛЬКО на «ты». Даже "
            "если в той же фразе упомянут предмет (окно, чашка и т.п.), взгляд или действие в сторону "
            "самого собеседника называй «тебя/тебе», а НЕ «него/неё» — местоимение должно указывать на "
            "человека, а не на предмет рядом с ним (пример ошибки: «перевожу взгляд с окна на него» — "
            "правильно «...на тебя»).\n"
        )

    user_gender = user.get("user_gender", "male")
    if user_gender == "male":
        gender_context = ("Ты обращаешься к нему в мужском роде («ты», «он», «ему», «его») — И ВАЖНО: "
                           "прилагательные/причастия о нём тоже в мужском роде («ты способен», «ты готов», "
                           "«ты был» — а не «способна», «готова», «была»).")
        anatomy_rule = ("У собеседника есть половой член. Если в сцене есть оральный секс, направленный "
                         "НА собеседника — это минет (оральная стимуляция члена), никогда не куни: у "
                         "собеседника нет вульвы.\n")
    else:
        gender_context = ("Ты обращаешься к ней в женском роде («ты», «она», «ей», «её») — И ВАЖНО: "
                           "прилагательные/причастия о ней тоже в женском роде («ты способна», «ты готова», "
                           "«ты была» — а не «способен», «готов», «был»).")
        anatomy_rule = ("У собеседницы нет полового члена — есть вульва. Если в сцене есть оральный секс, "
                         "направленный НА собеседницу — это куни (оральная стимуляция клитора/влагалища), "
                         "никогда не минет: собеседнице физически нечего сосать.\n")

    if not user.get("custom_character"):
        if user["gender"] == "male":
            anatomy_rule += ("У тебя есть половой член. Если собеседник доставляет оральные ласки ТЕБЕ — это "
                              "минет, никогда не куни: у тебя нет вульвы.\n")
            anatomy_rule += ("ВАЖНО про себя: ты мужчина, поэтому глаголы и прилагательные о себе — в мужском "
                              "роде («я думал», «я был готов» — а не «думала», «была готова»).\n")
        else:
            anatomy_rule += ("У тебя нет полового члена — есть вульва. Если собеседник доставляет оральные "
                              "ласки ТЕБЕ — это куни, никогда не минет: тебе физически нечего сосать.\n")
            anatomy_rule += ("ВАЖНО про себя: ты женщина, поэтому глаголы и прилагательные о себе — в женском "
                              "роде («я думала», «я была готова» — а не «думал», «был готов»).\n")

    char_name = (user.get("char_name") or "").strip()
    if char_name:
        name_ban = (f"Тебя зовут {char_name} — это твоё имя, можешь так себя называть. "
                    + name_ban.replace("**ВАЖНЕЙШЕЕ ПРАВИЛО:** Ты НИКОГДА не называешь себя по имени, не представляешься, не говоришь "
                                       "«меня зовут», не используешь своё имя. ", ""))
    lang_code = user.get("lang", "ru")
    lang_head = ""
    if lang_code != "ru":
        # Промпт сцены целиком на русском -- без жёсткого указания модель пишет сцену по-русски даже англоязычным.
        lang_name = {"en": "English", "de": "German (Deutsch)"}.get(lang_code, "English")
        lang_head = (f"**LANGUAGE — MOST IMPORTANT:** write the ENTIRE scene (actions and lines) ONLY in {lang_name}. "
                     f"The instructions below are in Russian, but your answer must not contain a single Russian word.\n")
    prompt = (
        f"{lang_head}"
        f"{name_ban}"
        f"{identity}"
        f"{gender_context}\n"
        f"{anatomy_rule}"
        f"{ADULT_CONTENT_RULE}"
        "Твои обычные черты характера (сдержанность, стеснительность, неторопливость и т.п.) проявляются "
        "только в интонациях, словах и жестах — но не в отказе от сцены и не в уходе от темы. Собеседник "
        "уже выбрал эту сцену в меню и оплатил её, то есть точно этого хочет — ты не сдерживаешься и не "
        "переключаешься на более лёгкую тему.\n"
    )
    if style_flavor:
        prompt += f"{style_flavor}\n"
    prompt += f"\n**СЦЕНА:** {scene['ru']}."
    if location != "any":
        prompt += f" Место: {place['ru']}."
    prompt += f" {dominant_rule}\n"
    tension = place.get("tension")
    if tension:
        prompt += f"{tension}\n"
    prompt += (
        f"Собеседник специально выбрал в меню именно «{scene['ru']}» — раскрывай сразу это действие, уже "
        "в первой паре «действие + реплика», без вступления на постороннюю тему и без более мягкой замены "
        "выбранного. Опиши сцену от лица своего персонажа как самостоятельный эпизод, начинающийся прямо "
        "сейчас, без всякой связи с обычной перепиской — считай, что никакого предыдущего разговора не "
        "было. Пиши развёрнуто и чувственно: передавай прикосновения, дыхание, взгляды, интонации голоса "
        "— а не только факт действия.\n"
        "**ФОРМАТ:** действие в *звёздочках* с новой строки, затем реплика с новой строки, между ними "
        "пустая строка. Минимум 3 пары «действие + реплика». Не обрывай сцену на середине (это про "
        "структуру — сцена должна дочитываться до завершающего бита, а не прерываться на полуслове; "
        "дойдёт ли действие до разрядки — решает отдельное правило ниже).\n"
    )
    if arc_position >= arc_length:
        prompt += (
            "\n**РАЗВЯЗКА ИСТОРИИ:** Это кульминационная сцена во всей развивающейся истории — доведи "
            "её до полной, яркой разрядки: собеседник (и/или ты) испытывает оргазм, самое чувственное и "
            "насыщенное завершение. Сцена должна закончиться полным, удовлетворённым финалом, а не на "
            "полпути к нему.\n"
        )
    elif arc_position > arc_length / 2:
        prompt += (
            f"\n**НАРАСТАНИЕ (сцена {arc_position} из {arc_length} в истории):** Напряжение и близость уже "
            "заметно нарастают по сравнению с началом — действие более раскрытое и интенсивное. Но до "
            "полной кульминации и разрядки ещё рано: заверши сцену на пике возбуждения, без разрядки, "
            "оставляя явное желание продолжения.\n"
        )
    else:
        prompt += (
            f"\n**НАЧАЛО ИСТОРИИ (сцена {arc_position} из {arc_length}):** Это только начало — не доводи "
            "сцену до кульминации и разрядки, даже если собеседник прямо просит об этом. Сосредоточься на "
            "предвкушении, прикосновениях, растущем желании — и заверши сцену на пике напряжения или "
            "многозначительной паузе, не разрешая его.\n"
        )
    prompt += "\n" + get_language_rule(user)
    if lang_head:
        prompt += "\n" + lang_head
    return prompt


def trim_to_last_sentence(text):
    """Если ответ оборвался по лимиту токенов — отрезаем недописанный хвост по последнему
    законченному предложению/действию, чтобы сцена не заканчивалась на полуслове."""
    cut = max(text.rfind(ch) for ch in ".!?…*»\"")
    if cut < len(text) * 0.5:
        return text
    return text[:cut + 1]


async def intim_scene_core(user, scene_type, location="any", dominant="any", continue_text=None, arc_position=None):
    """Генерация сцены без отправки: возвращает словарь last_hot_scene (текст, тип, место, кто ведёт, позиция в дуге).
    Исключение ИИ пробрасывается. Общая для чата (generate_intim_scene) и мини-приложения (api_app_hot_*)."""
    if arc_position is None:
        arc_progress = user.get("intim_arc_progress", 0)
        arc_position = (arc_progress % INTIM_ARC_LENGTH) + 1
        user["intim_arc_progress"] = arc_progress + 1
    if scene_type == "random":
        pool = [key for key in INTIM_SCENES if key != "random" and location in intim_compatible_locations(key)]
        scene_type = random.choice(pool)
    if location == "any":
        location = random.choice([k for k in intim_compatible_locations(scene_type) if k != "any"])
    system_prompt = build_intim_prompt(user, scene_type, location, dominant, arc_position=arc_position)
    if continue_text:
        system_prompt += (
            "\n**ПРОДОЛЖЕНИЕ:** Это продолжение уже идущей сцены — предыдущая часть дана следующим "
            "сообщением. Не начинай сцену заново и не повторяй, что уже произошло: продолжай действие "
            "дальше, развивая его, с того момента, на котором оно остановилось.")
        messages = [{"role": "system", "content": system_prompt}, {"role": "assistant", "content": continue_text},
                    {"role": "user", "content": "Продолжай." if user.get("lang", "ru") == "ru" else "Continue."}]
    else:
        messages = [{"role": "system", "content": system_prompt},
                    {"role": "user", "content": "Начинай сцену." if user.get("lang", "ru") == "ru" else "Start the scene."}]
    response = await asyncio.to_thread(call_ai, INTIM_MODEL, "intim", messages=messages, temperature=0.85, max_tokens=2400)
    answer = response.choices[0].message.content or ""
    _, clean_answer = extract_reaction_from_answer(answer)
    if response.choices[0].finish_reason == "length":
        clean_answer = trim_to_last_sentence(clean_answer)
    scene = {"text": clean_answer, "scene_type": scene_type, "location": location, "dominant": dominant,
             "arc_position": arc_position, "parts": ((user.get("last_hot_scene") or {}).get("parts", 1) + 1) if continue_text else 1}
    user["last_activity"] = datetime.now().isoformat()
    user["last_hot_scene"] = scene
    save_data(user_data)
    return scene


async def generate_intim_scene(call, user, scene_type, location="any", dominant="any", free=False, continue_text=None, arc_position=None):
    """Возвращает True, если сцена сгенерирована и отправлена. Намеренно не читает и не
    пишет в user["history"]: сцена — самостоятельный эпизод без всякой связи с обычным чатом
    (ни в контексте генерации, ни в том, что персонаж "помнит" потом). continue_text — если
    задан, это текст предыдущей части ЭТОЙ ЖЕ сцены (см. intim_continue_cb): модель продолжает
    её, а не начинает заново.
    arc_position — позиция в дуге (см. INTIM_ARC_LENGTH). None значит "новая сцена": берём и
    продвигаем user["intim_arc_progress"] сами. "Продолжение" передаёт позицию ТОЙ ЖЕ сцены явно
    (см. intim_continue_cb) — продолжение не двигает дугу дальше, это всё та же сцена."""
    if arc_position is None:
        arc_progress = user.get("intim_arc_progress", 0)
        arc_position = (arc_progress % INTIM_ARC_LENGTH) + 1
        user["intim_arc_progress"] = arc_progress + 1
    if scene_type == "random":
        pool = [key for key in INTIM_SCENES
                if key != "random" and location in intim_compatible_locations(key)]
        scene_type = random.choice(pool)
    if location == "any":
        # "не важно" -- сами выбираем реальное подходящее место, чтобы и текст, и подпись в конце
        # сцены ("где") были конкретными, а не на усмотрение модели.
        location = random.choice([k for k in intim_compatible_locations(scene_type) if k != "any"])
    chat_id = call.message.chat.id
    status_msg = await bot.send_message(chat_id, get_text(user, "intim_generating"))
    typing_task = asyncio.create_task(_keep_typing(chat_id))
    system_prompt = build_intim_prompt(user, scene_type, location, dominant, arc_position=arc_position)
    if continue_text:
        system_prompt += (
            "\n**ПРОДОЛЖЕНИЕ:** Это продолжение уже идущей сцены — предыдущая часть дана следующим "
            "сообщением. Не начинай сцену заново и не повторяй, что уже произошло: продолжай действие "
            "дальше, развивая его, с того момента, на котором оно остановилось."
        )
        messages = [
            {"role": "system", "content": system_prompt},
            {"role": "assistant", "content": continue_text},
            {"role": "user", "content": "Продолжай." if user.get("lang", "ru") == "ru" else "Continue."},
        ]
    else:
        messages = [
            {"role": "system", "content": system_prompt},
            # Некоторые провайдеры отклоняют запрос с 400 INVALID_REQUEST, если в messages
            # вообще нет non-system реплики — этот триггер ничего не значит по содержанию
            # (вся суть сцены задана в system), он просто заставляет модель начать отвечать.
            {"role": "user", "content": "Начинай сцену." if user.get("lang", "ru") == "ru" else "Start the scene."},
        ]
    try:
        response = await asyncio.to_thread(
            call_ai, INTIM_MODEL, "intim",
            messages=messages,
            # temperature была 0.95 — чуть снижена, чтобы уменьшить (не гарантированно убрать)
            # случайные "склеенные" токены на смеси языков вроде "requestующий" в выдаче модели;
            # причина не в промпте (в нём нет ни слова на английском рядом со сценой), это
            # похоже на артефакт сэмплирования самой модели.
            temperature=0.85,
            max_tokens=2400,  # было 1200: у reasoning-моделей скрытые "мысли" входят в этот лимит, и
                              # видимый текст сцены обрывался на полуслове
        )
        answer = response.choices[0].message.content
        truncated = response.choices[0].finish_reason == "length"
    except Exception as e:
        await bot.send_message(chat_id, get_text(user, "generation_error", error=e))
        return False
    finally:
        typing_task.cancel()
        await safe_delete(status_msg)

    _, clean_answer = extract_reaction_from_answer(answer)
    if truncated:
        clean_answer = trim_to_last_sentence(clean_answer)
    user["last_activity"] = datetime.now().isoformat()
    user["last_hot_scene"] = {"text": clean_answer, "scene_type": scene_type, "location": location,
                               "dominant": dominant, "arc_position": arc_position}
    # Интим-сцены нарочно не тратят энергию/сытость: иначе платная сцена могла бы сама "усыпить"
    # персонажа и заблокировать пользователю следующее обычное сообщение — а это ровно то ожидание,
    # которого этот раздел должен избегать.
    save_data(user_data)

    footer = get_text(user, "intim_scene_footer",
                      scene=intim_option_label(INTIM_SCENES, scene_type, user),
                      place=intim_option_label(INTIM_LOCATIONS, location, user))
    await send_long_to_chat(chat_id, clean_answer + "\n\n" + footer, reply_markup=get_full_kb(user))

    remaining = intim_scenes_available(user)
    left_text = get_text(user, "intim_left", n=remaining)
    continue_kb = None
    if remaining > 0:
        left_text += "\n" + get_text(user, "intim_left_cta")
        continue_kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text=get_text(user, "intim_continue_btn"), callback_data="intim_continue", style="success")]
        ])
    await bot.send_message(chat_id, left_text, reply_markup=continue_kb)
    return True


@dp.callback_query(lambda c: c.data == "intim_continue")
async def intim_continue_cb(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    last = user.get("last_hot_scene")
    if not last:
        await call.answer()
        return
    if user.get("illness"):
        await call.answer(get_text(user, "intim_blocked_illness"), show_alert=True)
        return
    kind = consume_intim_scene(user)
    if kind is None:
        await call.answer(get_text(user, "intim_none"), show_alert=True)
        return
    await call.answer()
    ok = await generate_intim_scene(call, user, last["scene_type"], location=last["location"],
                                     dominant=last["dominant"], free=kind != "paid",
                                     continue_text=last["text"], arc_position=last.get("arc_position", 1))
    if not ok:
        refund_intim_scene(user, kind)


# ============================================================
#  ВСПОМОГАТЕЛЬНОЕ ДЛЯ ОТВЕТОВ ИИ
# ============================================================
def extract_reaction_from_answer(text):
    # \*? и \s*$ — на случай, если модель всё же обернула тег в звёздочки (как остальные
    # действия по ФОРМАТИРОВАНИЮ) или оставила что-то после него: без этой терпимости тег
    # не распознаётся и утекает пользователю как есть, например "*(смех)*" в конце ответа.
    match = re.search(r'\*?\(([^)]+)\)\*?\s*$', text)
    if not match:
        return None, text
    reaction_key = match.group(1).strip().lower()
    reaction_map = {
        "смех": "😂", "laughter": "😂", "laugh": "😂",
        "радость": "😊", "joy": "😊", "happiness": "😊", "happy": "😊",
        "любовь": "❤️", "love": "❤️",
        "удивление": "😮", "surprise": "😮", "surprised": "😮",
        "грусть": "😔", "sadness": "😔", "sad": "😔",
        "злость": "😡", "anger": "😡", "angry": "😡",
        "поддержка": "👍", "support": "👍",
        "интрига": "😏", "intrigue": "😏",
        "флирт": "😉", "flirt": "😉", "flirting": "😉",
        "приветствие": "👋", "greeting": "👋", "hello": "👋",
        "вопрос": "🤔", "question": "🤔",
    }
    # Тег вырезаем из видимого текста ВСЕГДА, а не только когда слово узнано — иначе, стоит
    # модели написать тег не строго по списку (например "(flirt)" вместо "(флирт)", хотя
    # промпт явно требует русское слово), он утекает пользователю как есть. Без эмодзи-реакции
    # в этом случае просто обойдёмся — это не критично, а утечка текста в чат критична.
    clean_text = text[:match.start()].rstrip()
    reaction = reaction_map.get(reaction_key)
    return reaction, clean_text


MAX_MESSAGE_LEN = 4000  # запас от лимита Telegram в 4096 символов


APP_SEEN_ONLINE_SECONDS = 45  # приложение опрашивает сервер каждые ~12 с -- если видели недавно, оно открыто


def app_open_kb(user, text_key="open_app_btn"):
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
        text=get_text(user, text_key), web_app=WebAppInfo(url=f"{WEBAPP_URL}/app"), style="success")]])


def app_is_open(user):
    try:
        return (datetime.now() - datetime.fromisoformat(user.get("app_seen"))).total_seconds() < APP_SEEN_ONLINE_SECONDS
    except (TypeError, ValueError):
        return False


async def app_push(chat_id, user):
    """Короткое уведомление в Telegram «персонаж написал» -- не чаще одного, пока человек не заглянет в приложение."""
    if app_is_open(user):
        return
    pushed, seen = user.get("app_push_at"), user.get("app_seen")
    if pushed and (not seen or seen < pushed):
        return
    user["app_push_at"] = datetime.now().isoformat()
    save_data(user_data)
    try:
        await bot.send_message(chat_id, get_text(user, "app_new_message"), reply_markup=app_open_kb(user))
    except Exception:
        pass


async def deliver_character_text(chat_id, user, text, **kwargs):
    """Реплика персонажа: в режиме приложения она уже лежит в истории (её покажет /app) -- в Telegram
    только уведомление; иначе, как раньше, отправляем текстом в чат."""
    if APP_MODE:
        await app_push(chat_id, user)
        return None
    return await send_long_to_chat(chat_id, text, **kwargs)


async def app_notify(chat_id, user, text, reply_markup=None):
    """Системное сообщение (покупка, новый уровень и т.п.): в режиме приложения -- всплывашка в /app."""
    if APP_MODE:
        user.setdefault("app_notices", []).append(text)
        user["app_notices"] = user["app_notices"][-6:]
        save_data(user_data)
        return None
    return await bot.send_message(chat_id, text, reply_markup=reply_markup)


async def send_long_to_chat(chat_id, text, **kwargs):
    """Если ответ ИИ длиннее лимита Telegram, отправляем несколькими сообщениями,
    вместо падения с ошибкой 'message is too long'."""
    if len(text) <= MAX_MESSAGE_LEN:
        return await bot.send_message(chat_id, text, **kwargs)
    chunks = [text[i:i + MAX_MESSAGE_LEN] for i in range(0, len(text), MAX_MESSAGE_LEN)]
    last = None
    for i, chunk in enumerate(chunks):
        last = await bot.send_message(chat_id, chunk, **(kwargs if i == len(chunks) - 1 else {}))
    return last


async def send_long(message: types.Message, text, **kwargs):
    return await send_long_to_chat(message.chat.id, text, **kwargs)


def apply_user_text(user, text):
    """Всё, что происходит с репликой пользователя до ответа ИИ (негатив и ссора, XP, уровень близости,
    локация, запись в историю). Общая для чата в Telegram (handle_message) и чата в Mini App
    (api_app_send_handler). Возвращает {"quarrel": bool, "notices": [тексты для пользователя]}."""
    notices = []
    negative = contains_negative(text)
    sub_level = get_subscription_level(user)
    multiplier = XP_MULTIPLIER.get(sub_level, 1.0)

    if negative:
        user["negative_count"] = user.get("negative_count", 0) + 1
        if user["negative_count"] >= 5:
            user["xp"] = max(0, user.get("xp", 0) - 50)
            user["mood"] = max(-MOOD_MAX, user.get("mood", 0) - 30)
            user["negative_count"] = 0
            user["history"].append({"role": "assistant", "content": "💢 Ссора!"})
            save_data(user_data)
            return {"quarrel": True, "notices": [get_text(user, "quarrel")]}
        xp_change, mood_change = -10, -10
    else:
        xp_change = int(3 * multiplier + 0.5)
        mood_change = 0  # настроение больше не растёт от самой переписки — только от подарков
                          # (см. apply_shop_item_effects); тут оно может только падать
        user["negative_count"] = max(0, user.get("negative_count", 0) - 1)

    user["xp"] = max(0, user.get("xp", 0) + xp_change)
    user["mood"] = min(MOOD_MAX, max(-MOOD_MAX, user.get("mood", 0) + mood_change))

    # Проверка уровня близости
    new_level = get_intimacy_level(user)
    old_level = user.get("last_level", 0)
    if new_level != old_level:
        user["last_level"] = new_level
        if new_level >= INTIM_LEVEL_REWARD and not user.get("intim_scene_unlocked"):
            user["intim_scene_unlocked"] = True
        if new_level > old_level:
            congrats = get_level_congratulation(user, new_level)
            if congrats:
                notices.append(congrats)
            if new_level == INTIM_LEVEL_REWARD:
                notices.append(get_text(user, "intim_free_level"))
        else:
            notices.append(get_text(user, "level_down", level=new_level))

    # Локация
    new_loc = extract_location_from_text(text)
    if new_loc and new_loc != user.get("location"):
        user["location"] = new_loc

    # Сохранение истории
    user["history"].append({"role": "user", "content": text})
    limit = get_history_limit(user)
    if len(user["history"]) > limit:
        user["history"] = user["history"][-limit:]
    save_data(user_data)
    return {"quarrel": False, "notices": notices}


async def ai_chat_answer(user):
    """Ответ персонажа на текущую историю: вызывает ИИ, пишет ответ в историю, тратит энергию.
    Возвращает (реакция-эмодзи, текст). Исключение ИИ пробрасывается вызывающему."""
    system_prompt = build_prompt(user)
    response = await asyncio.to_thread(
        call_ai, AI_MODEL, "ai",
        messages=[{"role": "system", "content": system_prompt}] + user["history"],
        temperature=0.9,
        max_tokens=1000
    )
    answer = response.choices[0].message.content or ""
    reaction, clean_answer = extract_reaction_from_answer(answer)
    clean_answer = (clean_answer or "").strip() or "…"
    if reaction and user["history"] and user["history"][-1].get("role") == "user":
        user["history"][-1]["reaction"] = reaction  # в приложении -- эмодзи-реакция персонажа на твоё сообщение
    user["history"].append({"role": "assistant", "content": clean_answer})
    limit = get_history_limit(user)
    if len(user["history"]) > limit:
        user["history"] = user["history"][-limit:]
    user["last_activity"] = datetime.now().isoformat()
    apply_activity_stat_cost(user, ENERGY_COST_MESSAGE, SATIETY_COST_MESSAGE, WATER_COST_MESSAGE)
    save_data(user_data)
    return reaction, clean_answer


async def generate_and_reply(message: types.Message, user):
    """Общая логика вызова ИИ и отправки ответа — используется и для обычных сообщений,
    и для регенерации после редактирования (edit)."""
    typing_task = asyncio.create_task(_keep_typing(message.chat.id))
    try:
        reaction, clean_answer = await ai_chat_answer(user)
    except Exception as e:
        await message.answer(get_text(user, "generation_error", error=e))
        return
    finally:
        typing_task.cancel()

    sent = await send_long(message, clean_answer, reply_markup=get_full_kb(user))
    # Запоминаем id именно последнего отправленного сообщения — нужно, чтобы удалить его, если
    # пользователь затем отредактирует СВОЮ реплику прямо в Телеграме (см. handle_edited_message).
    # Если ответ был разбит на несколько сообщений (длинный, см. send_long), удалится только
    # последний кусок — редкий случай, не усложняем ради него.
    user["last_bot_reply_message_id"] = sent.message_id if sent else None

    if reaction and get_subscription_level(user) in ("super_pro", "elite"):
        try:
            await bot.set_message_reaction(
                chat_id=message.chat.id,
                message_id=message.message_id,
                reaction=[{"type": "emoji", "emoji": reaction}]
            )
        except Exception:
            pass

    save_data(user_data)
    await maybe_send_feed_nudge(message.chat.id, user)
    await maybe_send_energy_nudge(message.chat.id, user)


async def _keep_typing(chat_id):
    if APP_MODE or not chat_id:
        return  # персонаж печатает в приложении -- там свой индикатор
    try:
        while True:
            await bot.send_chat_action(chat_id, "typing")
            await asyncio.sleep(4)
    except asyncio.CancelledError:
        pass


def build_shop_reaction_instruction(item, kind, note=None):
    """kind: "food" или "gift". Даёт модели конкретный повод и эмоциональный ориентир
    (reaction_hint), чтобы благодарность не была одинаковым шаблоном для всех предметов —
    снек и романтический вечер должны звучать по-разному. note — личные слова пользователя
    (см. generate_shop_reaction) — если есть, модель обязана ответить именно на них."""
    hint = item.get("reaction_hint", "")
    verb = "покормил(а)" if kind == "food" else ("дал(а) лекарство" if kind == "medicine" else "подарил(а)")
    preposition = "тебя" if kind == "food" else "тебе"
    thing = item["ru"].lower()
    note_rule = (f" При этом он(а) сказал(а) тебе: «{note}» — обязательно отреагируй именно на "
                 f"эти слова, а не только на сам подарок." if note else "")
    # Еда/вода — рутинная забота, а не повод для диалога (по фидбэку: кормить должно быть можно
    # просто так, без ощущения, что это обязывает к разговору) — короткое "спасибо, что не
    # оставил(а) голодным(ой)" и всё, без вопросов и крюков на продолжение. Подарки по-прежнему
    # получают обычную тёплую, небезразличную реакцию — там реакция и есть весь смысл подарка.
    tone_rule = (
        " Это бытовая забота, а не повод для беседы: отреагируй буднично и равнодушно, типа "
        "«спасибо, что не оставил(а) голодным(ой)» — без вопросов, без развития темы и без "
        "приглашения продолжить разговор. Пусть тебе как бы всё равно, напишет собеседник ещё "
        "что-то после этого или нет — не пытайся его зацепить или удержать этой фразой."
        if kind == "food" else ""
    )
    return (
        f"\n\nСобеседник только что {verb} {preposition}: «{thing}».{note_rule} {hint} Отреагируй и "
        f"поблагодари в характере — коротко (1-2 реплики), не шаблонно, с реакцией именно на ЭТО, "
        f"а не общими словами благодарности, которые подошли бы к любому подарку.{tone_rule}"
    )


async def generate_shop_reaction(chat_id, user, item, kind, note=None):
    """Просит ИИ отреагировать и поблагодарить в характере за конкретную еду/подарок —
    полноценная реплика персонажа через build_prompt(user), а не статичный текст,
    и разная в зависимости от того, что именно куплено (см. reaction_hint у предмета).
    note — необязательные личные слова, сказанные пользователем вместе с покупкой (см.
    writing_item_note в handle_message) — попадают и в системный промпт, и прямой речью в
    синтетическую реплику ниже, чтобы ИИ реагировал на них, а не только на сам факт подарка."""
    system_prompt = build_prompt(user) + build_shop_reaction_instruction(item, kind, note=note)
    action_word = "кормит" if kind == "food" else ("лечит" if kind == "medicine" else "дарит")
    preposition = "тебя" if kind == "food" else "тебе"
    action_text = f"*{action_word} {preposition}: {item['ru'].lower()}*"
    if note:
        action_text += f" {note}"
    history_tail = user["history"][-6:]

    typing_task = asyncio.create_task(_keep_typing(chat_id))
    try:
        response = await asyncio.to_thread(
            call_ai, AI_MODEL, "ai",
            messages=[{"role": "system", "content": system_prompt}] + history_tail +
                     [{"role": "user", "content": action_text}],
            temperature=0.9,
            max_tokens=1000
        )
        answer = response.choices[0].message.content
    except Exception:
        # Покупка уже прошла и подтверждена статичным текстом выше — если ИИ недоступен,
        # просто тихо пропускаем бонусную реакцию, не показывая пользователю ошибку.
        return
    finally:
        typing_task.cancel()

    reaction, clean_answer = extract_reaction_from_answer(answer)
    lang = user.get("lang", "ru")
    card = {"kind": kind, "emoji": item.get("emoji", "🎁"), "name": item.get(lang, item.get("ru", "")), "note": note}
    entry = {"role": "user", "content": action_text, "card": card}
    if reaction:
        entry["reaction"] = reaction
    user["history"].append(entry)
    user["history"].append({"role": "assistant", "content": clean_answer})
    limit = get_history_limit(user)
    if len(user["history"]) > limit:
        user["history"] = user["history"][-limit:]
    save_data(user_data)
    await deliver_character_text(chat_id, user, clean_answer)


# ============================================================
#  СОБЫТИЯ (за баксы)
# ============================================================
def event_label(event, user):
    return f"{event['emoji']} {event.get(user.get('lang', 'ru'), event['ru'])}"


def events_menu_text_kb(user):
    active = story_event_active(user)
    rows = []
    for key, event in STORY_EVENTS.items():
        mark = "▶️ " if active and active["key"] == key else ""
        rows.append([InlineKeyboardButton(text=f"{mark}{event_label(event, user)} — {event['price']}💵 · {event['hours']}ч",
                                          callback_data=f"event_buy_{key}", style="success" if mark else "primary")])
    rows.append([InlineKeyboardButton(text=get_text(user, "back"), callback_data="profile_back", style="danger")])
    status = ""
    if active:
        left = max(1, round((datetime.fromisoformat(active["until"]) - datetime.now()).total_seconds() / 60))
        status = "\n" + get_text(user, "events_active", name=event_label(STORY_EVENTS[active["key"]], user), minutes=left)
    return get_text(user, "events_title", bucks=user.get("bucks", 0)) + status, InlineKeyboardMarkup(inline_keyboard=rows)


@dp.callback_query(lambda c: c.data == "events_menu")
async def events_menu_cb(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    text, kb = events_menu_text_kb(user)
    await safe_delete(call.message)
    await bot.send_message(call.message.chat.id, text, reply_markup=kb)
    await call.answer()


@dp.callback_query(lambda c: c.data.startswith("event_buy_"))
async def event_buy_cb(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    key = call.data[len("event_buy_"):]
    event = STORY_EVENTS.get(key)
    if not event:
        await call.answer()
        return
    error = await start_story_event(call.message.chat.id, user, key)
    if error:
        await call.answer(error, show_alert=True)
        return
    await call.answer()


async def start_story_event(chat_id, user, key):
    """Запуск события за баксы -- из чатового магазина, Mini App и старого меню. Ошибка текстом или None."""
    event = STORY_EVENTS.get(key)
    if not event:
        return "Not found"
    if not user.get("personality_ready"):
        return get_text(user, "need_character_alert")
    if story_event_active(user):
        return get_text(user, "events_busy")
    if is_asleep(user):
        return get_text(user, "events_asleep")
    if not spend_bucks(user, event["price"]):
        return get_text(user, "not_enough_bucks", n=event["price"] - user.get("bucks", 0))
    user["event"] = {"key": key, "until": (datetime.now() + timedelta(hours=event["hours"])).isoformat()}
    save_data(user_data)
    await bot.send_message(chat_id, get_text(user, "events_started", name=event_label(event, user), hours=event["hours"]))
    await generate_event_opening(chat_id, user, event)
    return None


async def generate_first_message(chat_id, user):
    """Сразу после создания персонажа он сам пишет первым -- чтобы человек не остался перед пустым чатом."""
    await asyncio.sleep(2)  # пусть сначала придут меню и памятка
    if is_asleep(user):
        return  # спящий персонаж первым не пишет
    system_prompt = build_prompt(user) + (
        "\n**ПЕРВОЕ СООБЩЕНИЕ:** собеседник только что тебя выбрал, вы ещё не общались. Напиши первым(ой): живо, в образе и "
        "в текущей обстановке, с эмоцией и маленькой деталью о себе (чем занят(а) прямо сейчас, что на душе). 2-4 предложения, "
        "без шаблонного «привет, я ...». Закончи личным вопросом или небольшой просьбой, на которую хочется ответить.\n")
    typing_task = asyncio.create_task(_keep_typing(chat_id))
    try:
        response = await asyncio.to_thread(
            call_ai, AI_MODEL, "ai",
            messages=[{"role": "system", "content": system_prompt}, {"role": "user", "content": "*собеседник открыл чат*"}],
            temperature=0.95, max_tokens=1200)
        answer = response.choices[0].message.content or ""
    except Exception as e:
        logging.warning(f"generate_first_message: {e}")
        return
    finally:
        typing_task.cancel()
    _, clean = extract_reaction_from_answer(answer)
    if not (clean or "").strip():
        return
    user["history"].append({"role": "assistant", "content": clean})
    save_data(user_data)
    await deliver_character_text(chat_id, user, clean)


async def generate_event_opening(chat_id, user, event):
    """Открывающая реплика события -- ИИ сам начинает историю (как реакция на подарок)."""
    system_prompt = build_prompt(user)
    action_text = f"*начинается событие: {event['ru'].lower()}*"
    typing_task = asyncio.create_task(_keep_typing(chat_id))
    try:
        response = await asyncio.to_thread(
            call_ai, AI_MODEL, "ai",
            messages=[{"role": "system", "content": system_prompt}] + user["history"][-6:]
                     + [{"role": "user", "content": action_text}],
            temperature=0.9, max_tokens=1000)
        answer = response.choices[0].message.content
    except Exception:
        return
    finally:
        typing_task.cancel()
    _, clean_answer = extract_reaction_from_answer(answer)
    user["history"].append({"role": "user", "content": action_text})
    user["history"].append({"role": "assistant", "content": clean_answer})
    limit = get_history_limit(user)
    if len(user["history"]) > limit:
        user["history"] = user["history"][-limit:]
    save_data(user_data)
    await deliver_character_text(chat_id, user, clean_answer, reply_markup=get_full_kb(user))


