def gt(user, key, **kw):
    lang = "ru" if user.get("lang", "ru") == "ru" else "en"
    value = GAME_TEXTS[lang][key]
    return value.format(**kw) if kw and isinstance(value, str) else value


CITIES_PRIZE = 0     # без денег: награда -- только XP (по фидбэку)
CITIES_XP = 30
# Развлечения покупаются в магазине (вкладка «🎮 Развлечения») и стартуют сразу, без билетов. price=0 у
# блэкджека: там платишь ставкой. Оставшиеся старые билеты (game_tickets) засчитываются как оплата.
GAME_OFFERS = {
    # Развлечения бесплатные (по фидбэку: "чтобы было реалистично") -- кроме кино и блэкджека (там ставки).
    "cities": {"emoji": "🏙", "ru": "Города", "en": "Cities", "price": 0},
    "tod": {"emoji": "🤫", "ru": "Правда или действие", "en": "Truth or dare", "price": 0},
    "bj": {"emoji": "🃏", "ru": "Блэкджек", "en": "Blackjack", "price": 0},
    "movie": {"emoji": "🎬", "ru": "Кино вместе", "en": "Movie together", "price": 2250},  # кино -- за баксы
    "rps": {"emoji": "✊", "ru": "Камень, ножницы, бумага", "en": "Rock, paper, scissors", "price": 0},
}


def game_tickets_have(user, key):
    return (user.get("game_tickets") or {}).get(key, 0)


def game_offer_name(user, key):
    offer = GAME_OFFERS[key]
    return offer["ru"] if user.get("lang", "ru") == "ru" else offer["en"]


def game_price_label(user, key):
    price = GAME_OFFERS[key]["price"]
    if key == "bj":
        return gt(user, "bj_price")
    return f"{price}💵" if price else gt(user, "play_free")


def pay_for_game(user, key):
    """Списывает оплату за партию: старый билет, если остался, иначе баксы. Возвращает сумму (0 за билет) или None."""
    if not GAME_OFFERS[key]["price"]:
        return 0  # бесплатная игра -- старые билеты не тратим
    tickets = user.get("game_tickets") or {}
    if tickets.get(key, 0) > 0:
        tickets[key] -= 1
        return 0
    price = GAME_OFFERS[key]["price"]
    if not spend_bucks(user, price):
        return None
    return price


# «💎 За баксы»: цель, ради которой баксы хочется копить. Энергетики и прокрут сюда намеренно не входят --
# их покупают только за звёзды (по решению владельца). Горячая сцена -- раз в неделю.
BUCKS_EXCHANGE = {
    "energizer": {"emoji": "⚡", "ru": "1 энергетик", "en": "1 energizer", "price": 12000},
    "defib": {"emoji": "🔌", "ru": "Дефибриллятор", "en": "Defibrillator", "price": 20000},
    "scene": {"emoji": "🔥", "ru": "Горячая сцена", "en": "Hot scene", "price": 30000},
}
# Что продаётся сегодня: каждый день что-то одно и купить можно один раз -- глоток бесплатного удовольствия,
# после которого хочется ещё (а дальше -- только за звёзды). Энергетик чаще остальных.
EXCHANGE_ROTATION = ["energizer", "defib", "energizer", "scene", "energizer", "defib", "energizer"]


def exchange_today():
    return EXCHANGE_ROTATION[local_today().toordinal() % len(EXCHANGE_ROTATION)]


def exchange_left(user, key):
    if key != exchange_today():
        return 0
    return 0 if (user.get("bucks_exchange") or {}).get("day") == local_today().isoformat() else 1


def exchange_name(user, key):
    offer = BUCKS_EXCHANGE[key]
    return offer["ru"] if user.get("lang", "ru") == "ru" else offer["en"]


def buy_exchange(user, key):
    """(ok, error_text). Сегодняшний товар за баксы, один раз в день."""
    offer = BUCKS_EXCHANGE.get(key)
    if not offer or key != exchange_today():
        return False, gt(user, "ex_not_today")
    if exchange_left(user, key) <= 0:
        return False, gt(user, "ex_limit_day")
    if not spend_bucks(user, offer["price"]):
        return False, get_text(user, "not_enough_bucks", n=offer["price"] - user.get("bucks", 0))
    if key == "energizer":
        user["energizers"] = user.get("energizers", 0) + 1
    elif key == "scene":
        user["intim_scenes"] = user.get("intim_scenes", 0) + 1
    elif key == "defib":
        if user.get("dead"):
            user["dead"] = False  # уже мёртв -- сразу воскрешаем
        else:
            user["defib_stock"] = user.get("defib_stock", 0) + 1  # иначе лежит в запасе до случая
    user["bucks_exchange"] = {"day": local_today().isoformat()}
    save_data(user_data)
    return True, None


def play_link_kb(user, game="rps"):
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(
        text=gt(user, "play_open_btn"), web_app=WebAppInfo(url=f"{WEBAPP_URL}/app?tab=games&game={game}"), style="success")]])


async def start_game(chat_id, user, key):
    """Единый запуск развлечения из меню, чатового магазина и Mini App. Возвращает текст ошибки или None."""
    if key not in GAME_OFFERS:
        return "Not found"
    error = games_gate_error(user)
    if error:
        return error
    if WEBAPP_URL:
        # Все игры теперь в мини-приложении (там анимации, звук и мини-чат партии).
        await bot.send_message(chat_id, gt(user, "play_open_text"), reply_markup=play_link_kb(user, key))
        return None
    if key == "rps" and WEBAPP_URL:
        # КНБ теперь в мини-приложении (/play): там анимация, звук и режим на раздевание; оплата -- внутри.
        await bot.send_message(chat_id, gt(user, "play_open_text"), reply_markup=play_link_kb(user))
        return None
    if key == "bj":
        if WEBAPP_URL:
            await bot.send_message(chat_id, gt(user, "play_open_text"), reply_markup=play_link_kb(user, "bj"))
        else:
            await send_bj_bets(chat_id, user)
        return None
    if key == "movie":
        await send_movie_genres(chat_id, user)
        return None
    paid = pay_for_game(user, key)
    if paid is None:
        price = GAME_OFFERS[key]["price"]
        return get_text(user, "not_enough_bucks", n=price - user.get("bucks", 0))
    if key == "cities":
        user["game"] = {"type": "cities", "used": [], "last": None, "moves": 0, "started": datetime.now().isoformat(), "paid": paid}
        game_touch(user["game"])
        save_data(user_data)
        await bot.send_message(chat_id, gt(user, "cities_start"), reply_markup=cities_kb(user))
    elif key == "tod":
        user["game"] = {"type": "tod", "round": 0, "phase": "pick", "busy": False}
        game_touch(user["game"])
        save_data(user_data)
        await bot.send_message(chat_id, gt(user, "tod_start", rounds=TOD_ROUNDS))
        await tod_send_pick(chat_id, user)
    elif key == "rps":
        user["game"] = {"type": "rps", "me": 0, "ai": 0, "busy": False}
        game_touch(user["game"])
        save_data(user_data)
        await bot.send_message(chat_id, gt(user, "rps_start", wins=RPS_WINS), reply_markup=rps_kb(user))
    return None
