CITY_LIST = sorted({c.strip() for c in CITIES.split("|") if c.strip()})


def city_norm(name):
    name = name.lower().replace("ё", "е").strip()
    name = re.sub(r"^(г\.|город)\s*", "", name)
    return re.sub(r"\s+", " ", name)


CITY_BY_NORM = {city_norm(c): c for c in CITY_LIST}


def city_last_letter(name):
    n = city_norm(name)
    for ch in reversed(n):
        if ch in "ьъый -":
            continue
        return ch
    return n[-1]


def city_first_letter(name):
    return city_norm(name)[0]


async def game_ai_line(chat_id, user, instruction, tail=None, max_tokens=1200):
    """Короткая реплика персонажа в образе по инструкции игры; тратит энергию как обычное сообщение."""
    if game_ai_lines_left(user) <= 0:
        return None  # дневной лимит реплик исчерпан -- партию можно доиграть без комментариев ИИ
    system_prompt = build_prompt(user) + "\n**ИГРА:** " + instruction + " Ответь 1-3 короткими предложениями, без списков.\n"
    messages = [{"role": "system", "content": system_prompt}] + (tail or []) + [{"role": "user", "content": "Твой ход."}]
    typing = asyncio.create_task(_keep_typing(chat_id))
    try:
        # max_tokens с запасом: у reasoning-моделей скрытые «мысли» входят в лимит, и при 350 ответ
        # часто приходил пустым -- в чате было просто «…» (баг из фидбэка).
        response = await asyncio.to_thread(call_ai, AI_MODEL, "ai", messages=messages, temperature=0.9, max_tokens=max_tokens)
        text = response.choices[0].message.content or ""
    except Exception as e:
        logging.warning(f"game_ai_line: {e}")
        return None
    finally:
        typing.cancel()
    _, clean = extract_reaction_from_answer(text)
    if not (clean or "").strip():
        return None
    apply_activity_stat_cost(user, ENERGY_COST_MESSAGE, SATIETY_COST_MESSAGE, WATER_COST_MESSAGE)
    game_ai_line_used(user)
    return clean


def games_menu_kb(user):
    """«Сыграем ещё?» после партии -- те же развлечения, что во вкладке магазина: нажал -- заплатил -- играешь."""
    rows = [[InlineKeyboardButton(text=f"{offer['emoji']} {game_offer_name(user, key)} — {game_price_label(user, key)}",
                                  callback_data=f"game_{key}", style="success")] for key, offer in GAME_OFFERS.items()]
    if WEBAPP_URL:
        rows.append([InlineKeyboardButton(text=gt(user, "play_strip_btn"), web_app=WebAppInfo(url=f"{WEBAPP_URL}/play?game=strip"),
                                          style="danger")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


GAME_STALE_MINUTES = 10  # без ходов дольше -- партия сгорает (вход не возвращается)
CITIES_MAX_MINUTES = 10  # общий лимит времени партии в города
CITIES_MAX_MOVES = 15    # и лимит ходов игрока -- дальше "ничья", вход возвращается
GAME_AI_LINES_PER_DAY = {None: 40, "pro": 80, "super_pro": 120, "elite": 200}  # реплик ИИ в играх за сутки


def game_ai_lines_left(user):
    today = local_today().isoformat()
    used = user.get("game_ai_day") or {}
    count = used.get("count", 0) if used.get("date") == today else 0
    return max(0, GAME_AI_LINES_PER_DAY.get(get_subscription_level(user), 40) - count)


def game_ai_line_used(user):
    today = local_today().isoformat()
    used = user.get("game_ai_day") or {}
    count = used.get("count", 0) if used.get("date") == today else 0
    user["game_ai_day"] = {"date": today, "count": count + 1}


def game_touch(game):
    game["t"] = datetime.now().isoformat()


def game_is_stale(game):
    try:
        return (datetime.now() - datetime.fromisoformat(game["t"])).total_seconds() > GAME_STALE_MINUTES * 60
    except (KeyError, ValueError, TypeError):
        return True


def games_gate_error(user):
    """Текст причины, по которой играть сейчас нельзя, или None."""
    if not user.get("personality_ready"):
        return gt(user, "need_char")
    if user.get("game") and (game_is_stale(user["game"]) or user["game"].get("type") != "bj"):
        # брошенная или незаконченная партия (вход не возвращаем) -- новая игра просто заменяет её,
        # иначе застрявшее кино блокировало все остальные развлечения (баг из фидбэка)
        user["game"] = None
    if user.get("game"):
        return gt(user, "busy")
    if game_ai_lines_left(user) <= 0:
        return gt(user, "daily_limit")
    if is_asleep(user):
        return gt(user, "asleep")
    if user.get("illness"):
        return gt(user, "sick")
    return None


