async def cities_user_move(message: types.Message, user):
    game = user["game"]
    if is_asleep(user):
        user["game"] = None
        save_data(user_data)
        await message.answer(gt(user, "asleep"))
        return
    chat_id = message.chat.id
    norm = city_norm(message.text)
    city = CITY_BY_NORM.get(norm)
    need = city_last_letter(game["last"]) if game["last"] else None
    if not city:
        await message.answer(gt(user, "cities_unknown", letter=need.upper() if need else "—"), reply_markup=cities_kb(user))
        return
    if need and city_first_letter(city) != need:
        await message.answer(gt(user, "cities_wrong_letter", letter=need.upper()), reply_markup=cities_kb(user))
        return
    if city in game["used"]:
        await message.answer(gt(user, "cities_used"), reply_markup=cities_kb(user))
        return
    game_touch(game)
    game["moves"] = game.get("moves", 0) + 1
    try:
        too_long = (datetime.now() - datetime.fromisoformat(game["started"])).total_seconds() > CITIES_MAX_MINUTES * 60
    except (KeyError, ValueError, TypeError):
        too_long = True
    if game["moves"] > CITIES_MAX_MOVES or too_long:
        user["game"] = None
        user["bucks"] = user.get("bucks", 0) + game.get("paid", 0)  # время вышло -- ничья, вход возвращаем
        save_data(user_data)
        await message.answer(gt(user, "cities_timeup"), reply_markup=games_menu_kb(user))
        return
    game["used"].append(city)
    letter = city_last_letter(city)
    options = [c for c in CITY_LIST if c not in game["used"] and city_first_letter(c) == letter]
    if not options:
        await cities_finish(chat_id, user, won=True)
        await message.answer(gt(user, "cities_stuck", letter=letter.upper()))
        return
    mine = random.choice(options)
    game["used"].append(mine)
    game["last"] = mine
    next_letter = city_last_letter(mine)
    save_data(user_data)
    line = await game_ai_line(
        chat_id, user,
        f"Вы играете в города. Собеседник назвал «{city}». Ты называешь город «{mine}» — обязательно назови именно его, "
        f"в конце реплики. Следующий город собеседнику нужен на букву «{next_letter.upper()}». Реагируй в своём стиле: "
        "смейся, подначивай, радуйся.")
    save_data(user_data)
    # Название и нужная буква добавляем сами, а не надеемся на ИИ: игроку нужно точно знать мой город.
    await message.answer((line + "\n\n" if line else "") + f"🏙 {mine} — {gt(user, 'cities_your_letter', letter=next_letter.upper())}",
                         reply_markup=cities_kb(user))


# ---------- Правда или действие ----------
TOD_ROUNDS = 4
TOD_XP = 30


def tod_kb(user):
    return InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text=gt(user, "tod_truth"), callback_data="tod_pick_truth"),
         InlineKeyboardButton(text=gt(user, "tod_dare"), callback_data="tod_pick_dare")],
        [InlineKeyboardButton(text=gt(user, "tod_end"), callback_data="tod_end")]])


def tod_end_kb(user):
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text=gt(user, "tod_end"), callback_data="tod_end")]])


async def tod_send_pick(chat_id, user):
    game = user["game"]
    game["phase"] = "pick"
    game_touch(game)
    save_data(user_data)
    await bot.send_message(chat_id, gt(user, "tod_pick_prompt", n=game["round"] + 1, total=TOD_ROUNDS), reply_markup=tod_kb(user))


async def tod_finish(chat_id, user):
    user["game"] = None
    save_data(user_data)
    await bot.send_message(chat_id, gt(user, "tod_finished", xp=TOD_XP), reply_markup=games_menu_kb(user))
    await grant_gift_xp(chat_id, user, TOD_XP)


@dp.callback_query(lambda c: c.data in ("tod_pick_truth", "tod_pick_dare", "tod_end"))
async def tod_action_cb(call: types.CallbackQuery):
    user = get_user(call.from_user.id)
    game = user.get("game")
    if not game or game.get("type") != "tod":
        await call.answer()
        return
    chat_id = call.message.chat.id
    if call.data == "tod_end":
        await safe_delete(call.message)
        await call.answer()
        await tod_finish(chat_id, user)
        return
    # выбор принимается ровно один раз за ход: повторные нажатия и кнопки из старых сообщений игнорируем
    if game.get("phase") != "pick" or game.get("busy"):
        await call.answer(gt(user, "tod_wait"))
        return
    game["busy"] = True
    game["phase"] = "answer"
    game["kind"] = "truth" if call.data == "tod_pick_truth" else "dare"
    game_touch(game)
    save_data(user_data)
    await safe_delete(call.message)
    await call.answer()
    try:
        if game["kind"] == "truth":
            task = "Задай ему один личный, тёплый, чуть смущающий вопрос (правда); не пошлый, не про деньги и не про здоровье."
            word = "правду"
        else:
            task = ("Придумай одно безобидное весёлое задание, которое можно выполнить прямо в чате (описать, написать, придумать, "
                    "изобразить словами); без нарушений правил и без пошлости.")
            word = "действие"
        line = await game_ai_line(chat_id, user, f"Игра «правда или действие». Собеседник выбрал {word}. {task} Только один вопрос или задание.")
        if not line:  # ИИ не ответил -- берём вопрос/задание из запасного списка, а не «…»
            line = random.choice(gt(user, "tod_fallback_truth" if game["kind"] == "truth" else "tod_fallback_dare"))
        await bot.send_message(chat_id, line + "\n\n" + gt(user, "tod_answer_hint"), reply_markup=tod_end_kb(user))
    finally:
        game["busy"] = False
        save_data(user_data)


async def tod_user_text(message: types.Message, user):
    """Любое текстовое сообщение во время игры -- по фазе: ответ мне, вопрос мне, либо подсказка нажать кнопку."""
    game = user["game"]
    chat_id = message.chat.id
    if game.get("busy"):
        await message.answer(gt(user, "tod_wait"))
        return
    phase = game.get("phase")
    if phase == "pick":
        await message.answer(gt(user, "tod_use_buttons"), reply_markup=tod_kb(user))
        return
    text = message.text.strip()[:400]
    game["busy"] = True
    game_touch(game)
    try:
        if phase == "answer":
            game["phase"] = "ai_turn"
            save_data(user_data)
            line = await game_ai_line(chat_id, user, f"Игра «правда или действие». Собеседник ответил/выполнил: «{text}». Отреагируй в образе "
                                                      "(смех, удивление, смущение, поддержка), без осуждения.")
            if line:
                await bot.send_message(chat_id, line)
            game["ai_kind"] = random.choice(["truth", "dare"])
            game["phase"] = "ask"
            game_touch(game)
            save_data(user_data)
            await bot.send_message(chat_id, gt(user, "tod_ai_turn", kind=gt(user, f"tod_kind_{game['ai_kind']}"),
                                               what=gt(user, f"tod_what_{game['ai_kind']}")), reply_markup=tod_end_kb(user))
        elif phase == "ask":
            game["phase"] = "ai_answer"
            save_data(user_data)
            if game.get("ai_kind") == "truth":
                instr = (f"Игра «правда или действие». Ты выбрала правду, собеседник спросил: «{text}». Ответь честно и по-настоящему в образе, "
                         "от первого лица; если вопрос слишком грубый — мягко уйди от ответа с шуткой.")
            else:
                instr = (f"Игра «правда или действие». Ты выбрала действие, собеседник придумал: «{text}». Выполни это словами в образе "
                         "(опиши, что делаешь); если задание слишком грубое или нарушает правила — отшутись и предложи смягчить.")
            line = await game_ai_line(chat_id, user, instr)
            if line:
                await bot.send_message(chat_id, line)
            game["round"] += 1
            if game["round"] >= TOD_ROUNDS:
                game["busy"] = False
                await tod_finish(chat_id, user)
                return
            await tod_send_pick(chat_id, user)
    finally:
        if user.get("game") is game:
            game["busy"] = False
            save_data(user_data)


# ---------- Камень, ножницы, бумага ----------
RPS_WINS = 3   # до трёх побед
