# ============================================================
#  УВЕДОМЛЕНИЯ (ЕЖЕДНЕВНЫЕ И "СКУЧАЮ")
# ============================================================
MISS_YOU_INACTIVITY_DAYS = 2  # с какого дня без сообщений начинаем напоминать
MISS_YOU_INTERVAL_DAYS = 2  # не чаще чем раз в столько дней после предыдущего напоминания
SLEEP_REMINDER_INTERVAL_HOURS = 12  # раз в сколько часов мягко напоминаем, что персонаж всё ещё спит
SPIN_REMINDER_INTERVAL_DAYS = 1  # раз в сколько дней мягко напоминаем про доступный бесплатный прокрут
THIRST_REMINDER_WATER_THRESHOLD = 20  # тот же порог, что у "сильной жажды" в build_thirst_rule
THIRST_REMINDER_INTERVAL_HOURS = 10  # было 4 — если вода весь день не пополняется, это напоминание
                                       # каждые 4 часа само по себе становится назойливым (жалоба
                                       # пользователя); 10 часов — максимум 2-3 раза в сутки, но
                                       # всё ещё чаще, чем про голод (жажда острее)
HUNGER_REMINDER_INTERVAL_HOURS = 14  # было 6, по той же причине — не чаще пары раз в день


async def check_notifications():
    while True:
        try:
            now = datetime.now()
            today = now.date().isoformat()
            for user_id, user in list(user_data.items()):
                if not user.get("verified") or not user.get("personality_ready"):
                    continue
                # Мёртвому персонажу не шлём обычные напоминания (скучаю/спин/сон) — это
                # тонально дико, пока экран смерти не закрыт дефибриллятором или новым
                # персонажем; отдельного "напоминания о смерти" пока нет, не нужно плодить типы.
                if user.get("dead"):
                    continue

                # Дневной сброс (в т.ч. шанс заболеть и перерастание простуды в бронхит) раньше шёл
                # только когда сам пользователь писал боту — пропавший так и не узнавал о болезни.
                # Теперь тот же сброс тикает и в фоне, а о болезни приходит уведомление ниже.
                _reset_daily_quota_if_needed(user)

                # Обезвоживание должно тикать и потенциально убивать ФОНОВО, а не только у тех,
                # кто сам сейчас пишет боту: иначе у молча пропавшего пользователя сохранённое
                # значение воды никогда не дошло бы до нуля (пассивный расход иначе считается
                # лениво, только при следующем get_user()), water_zero_since никогда бы не
                # выставился, и смерть от обезвоживания никогда бы не сработала в фоне. Делаем
                # это ДО проверки notifications_muted ниже — смерть не должна становиться
                # отключаемой вместе с обычными напоминаниями.
                apply_passive_satiety_decay(user)
                water_zero_since = user.get("water_zero_since")
                if water_zero_since:
                    try:
                        hours_dry = (now - datetime.fromisoformat(water_zero_since)).total_seconds() / 3600
                    except (ValueError, TypeError):
                        hours_dry = 0
                    if hours_dry >= DEHYDRATION_DEATH_HOURS:
                        await kill_character(int(user_id), user, cause="dehydration")
                        continue
                    elif hours_dry >= DEHYDRATION_URGENT_HOURS and not user.get("dehydration_urgent_warned"):
                        # Второй, более тревожный пуш — когда до смерти реально остаётся меньше
                        # 2 часов (по фидбэку: предупреждать раньше/заметнее). Тоже не привязан к
                        # notifications_muted — та же логика, что и у смерти/первого предупреждения.
                        user["dehydration_urgent_warned"] = True
                        save_data(user_data)
                        try:
                            await bot.send_message(int(user_id), get_text(user, "dehydration_urgent_warning"))
                        except Exception:
                            pass
                    elif hours_dry >= DEHYDRATION_WARN_HOURS and not user.get("dehydration_warned"):
                        # Один явный пуш до смерти — раньше смерть от обезвоживания наступала
                        # вообще без предупреждения. Та же логика "до смерти, не нагом" — не
                        # привязываем к notifications_muted, как и саму смерть чуть выше.
                        user["dehydration_warned"] = True
                        save_data(user_data)
                        try:
                            await bot.send_message(int(user_id), get_text(user, "dehydration_warning"))
                        except Exception:
                            pass


                # Уведомление о болезни (и о том, что простуда перешла в бронхит). Не привязано к
                # notifications_muted: это важное событие, как и предупреждения о смерти выше.
                illness_now = user.get("illness")
                if illness_now and user.get("illness_notified") != illness_now:
                    user["illness_notified"] = illness_now
                    save_data(user_data)
                    info = ILLNESSES[illness_now]
                    try:
                        key = "illness_push_new" if illness_now == "cold" else "illness_push_worse"
                        nxt = ILLNESS_NEXT.get(illness_now)
                        text = get_text(user, key, emoji=info["emoji"], name=info.get(user.get("lang", "ru"), info["ru"]),
                                        need=medicine_need_text(user), gap=ILLNESS_DOSE_GAP_HOURS)
                        if nxt:
                            text += " " + get_text(user, "illness_push_next", hours=ILLNESS_ESCALATE_HOURS_BY[illness_now],
                                                   next=illness_name(user, nxt))
                        await bot.send_message(int(user_id), text, reply_markup=app_open_kb(user) if APP_MODE else None)
                    except Exception:
                        pass
                elif not illness_now and user.get("illness_notified"):
                    user["illness_notified"] = None

                # Отключение уведомлений — привилегия SUPER PRO: если подписка упала до PRO или
                # истекла, напоминания сами возобновятся — отдельно снимать флаг не нужно.
                if user.get("notifications_muted") and get_subscription_level(user) in ("super_pro", "elite"):
                    continue

                # 1) "Скучаю" — для давно пропавших. Если это условие сработало, ниже больше
                # ничего не шлём в этом же тике: человеку и так возвращаемся отдельным
                # сообщением, второе уведомление сразу следом было бы уже спамом.
                last_activity_raw = user.get("last_activity")
                last_activity = None
                if last_activity_raw:
                    try:
                        last_activity = datetime.fromisoformat(last_activity_raw)
                    except Exception:
                        last_activity = None

                if last_activity and (now - last_activity).days >= MISS_YOU_INACTIVITY_DAYS:
                    last_reminder = user.get("last_reminder")
                    due = True
                    if last_reminder:
                        try:
                            due = (now - datetime.fromisoformat(last_reminder)).days >= MISS_YOU_INTERVAL_DAYS
                        except Exception:
                            due = True
                    if due:
                        user["last_reminder"] = today
                        save_data(user_data)
                        try:
                            gender = user.get("gender", "female")
                            miss = random.choice(get_text(user, f"miss_you_{gender}"))
                            if APP_MODE and user.get("personality_ready"):
                                user["history"].append({"role": "assistant", "content": miss})
                                save_data(user_data)
                                await app_push(int(user_id), user)
                            else:
                                await bot.send_message(int(user_id), miss)
                        except Exception:
                            pass
                        continue  # только в тике, где реально отправили — иначе глушит ежедневный прокрут

                # 2) Персонаж всё ещё спит — лёгкое проактивное напоминание, отдельное от
                # жёсткого asleep_message (который показывается только в ответ на попытку
                # написать спящему персонажу). Отсчёт идёт от момента засыпания, а не от
                # первой проверки, — чтобы не дёргать человека через 5 минут после того, как
                # энергия дошла до нуля.
                if is_asleep(user):
                    baseline = user.get("last_sleep_reminder") or user.get("sleep_until")
                    due = True
                    if baseline:
                        try:
                            hours_since = (now - datetime.fromisoformat(baseline)).total_seconds() / 3600
                            due = hours_since >= SLEEP_REMINDER_INTERVAL_HOURS
                        except Exception:
                            due = True
                    if due:
                        user["last_sleep_reminder"] = now.isoformat()
                        save_data(user_data)
                        try:
                            await bot.send_message(int(user_id), get_text(user, "sleep_daily_reminder"),
                                                   reply_markup=get_wake_kb(user))
                        except Exception:
                            pass
                    # Раньше здесь был continue -- из-за него у персонажей, которые регулярно
                    # засыпают, напоминание про бесплатный прокрут колеса (ниже) почти никогда не
                    # доходило: пока персонаж спит, этот continue перехватывал тик раньше. Сон не
                    # должен блокировать напоминание о спине — оно не завязано на то, спит ли
                    # персонаж (прокрутить колесо можно и спящему).

                # 3) Доступен бесплатный прокрут колеса — не чаще раза в сутки, только пока он
                # реально не использован, и только если напоминание не отключено тумблером в
                # Mini App колеса (см. serialize_spin_state/api_spin_reminder_handler).
                if free_spins_left(user) > 0 and user.get("spin_reminder_enabled", False):
                    last_spin_reminder = user.get("last_spin_reminder")
                    due = True
                    if last_spin_reminder:
                        try:
                            due = (now - datetime.fromisoformat(last_spin_reminder)).days >= SPIN_REMINDER_INTERVAL_DAYS
                        except Exception:
                            due = True
                    if due:
                        user["last_spin_reminder"] = today
                        save_data(user_data)
                        try:
                            # Открыть без полного "🎰 Колесо фортуны" — такая кнопка уже есть на
                            # клавиатуре, дублировать подпись в самом напоминании незачем. Текст
                            # напоминания — случайный вариант из списка, а не одна и та же фраза
                            # каждый день (по фидбэку).
                            if WEBAPP_URL:
                                spin_reminder_btn = InlineKeyboardButton(
                                    text=get_text(user, "open_btn"),
                                    web_app=WebAppInfo(url=f"{WEBAPP_URL}/spin"), style="success")
                            else:
                                spin_reminder_btn = InlineKeyboardButton(
                                    text=get_text(user, "open_btn"),
                                    callback_data="spin_free", style="success")
                            kb = InlineKeyboardMarkup(inline_keyboard=[[spin_reminder_btn]])
                            await bot.send_message(int(user_id), random.choice(get_text(user, "spin_daily_reminder")), reply_markup=kb)
                        except Exception:
                            pass
                        # continue только если напоминание реально ушло в этом тике — раньше он
                        # срабатывал всегда, пока есть неиспользованный прокрут, и тем самым
                        # глушил все напоминания ниже (вода/еда/ферма) на весь день.
                        continue

                # 4) Низкий уровень воды — жажда тратится быстрее голода, поэтому и напоминание
                # чаще (см. THIRST_REMINDER_INTERVAL_HOURS). Отсчёт cooldown — от последнего
                # такого напоминания, а не от water_zero_since: иначе после первого сообщения
                # напоминания сразу посыпались бы одно за другим.
                if user.get("water", WATER_MAX) <= THIRST_REMINDER_WATER_THRESHOLD:
                    last_thirst_reminder = user.get("last_thirst_reminder")
                    due = True
                    if last_thirst_reminder:
                        try:
                            hours_since = (now - datetime.fromisoformat(last_thirst_reminder)).total_seconds() / 3600
                            due = hours_since >= THIRST_REMINDER_INTERVAL_HOURS
                        except Exception:
                            due = True
                    if due:
                        user["last_thirst_reminder"] = now.isoformat()
                        save_data(user_data)
                        try:
                            await bot.send_message(int(user_id), get_text(user, "thirsty_reminder"),
                                                   reply_markup=get_feed_nudge_kb(user))
                        except Exception:
                            pass
                    continue

                # 5) Низкая сытость — тот же порог, что у контекстной подсказки в чате
                # (FEED_NUDGE_SATIETY_THRESHOLD), но это отдельный, проактивный пуш: срабатывает,
                # даже если пользователь молчит и не может получить подсказку в ответ на сообщение.
                if user.get("satiety", SATIETY_MAX) <= FEED_NUDGE_SATIETY_THRESHOLD:
                    last_hunger_reminder = user.get("last_hunger_reminder")
                    due = True
                    if last_hunger_reminder:
                        try:
                            hours_since = (now - datetime.fromisoformat(last_hunger_reminder)).total_seconds() / 3600
                            due = hours_since >= HUNGER_REMINDER_INTERVAL_HOURS
                        except Exception:
                            due = True
                    if due:
                        user["last_hunger_reminder"] = now.isoformat()
                        save_data(user_data)
                        try:
                            await bot.send_message(int(user_id), get_text(user, "hungry_reminder"),
                                                   reply_markup=get_feed_nudge_kb(user))
                        except Exception:
                            pass
                    continue

                # 6) Ферма созрела (см. CROPS/farm_state) — в отличие от остальных напоминаний
                # выше это не интервальный повтор, а разовое событие за цикл: один пуш на любую
                # грядку, как только урожай на ней впервые становится готов, без повторов для той
                # же грядки, пока не соберут и не посадят заново (см. farm_harvest, сбрасывает
                # ready_notified вместе со всем слотом). Три грядки независимы, но пуш общий —
                # не спамить отдельным сообщением на каждую, если созрели сразу несколько.
                farm_snaps = farm_state(user)
                plots = user.get("farm_plots") or []
                any_newly_ready = False
                for i, snap in enumerate(farm_snaps):
                    if snap and snap["ready"] and i < len(plots) and plots[i] and not plots[i].get("ready_notified"):
                        plots[i]["ready_notified"] = True
                        any_newly_ready = True
                if any_newly_ready:
                    save_data(user_data)
                    try:
                        if WEBAPP_URL:
                            farm_btn = InlineKeyboardButton(
                                text=get_text(user, "open_btn"),
                                web_app=WebAppInfo(url=f"{WEBAPP_URL}/work?tab=farm"), style="success")
                            await bot.send_message(int(user_id), get_text(user, "farm_ready_push"),
                                                   reply_markup=InlineKeyboardMarkup(inline_keyboard=[[farm_btn]]))
                        else:
                            await bot.send_message(int(user_id), get_text(user, "farm_ready_push"))
                    except Exception:
                        pass
            save_data(user_data)
        except Exception as e:
            logging.error(f"Ошибка уведомлений: {e}")
        await asyncio.sleep(1800)  # проверка раз в 30 минут


# ============================================================
#  ЗАПУСК
# ============================================================
async def main():
    print("🚀 Role Duel запущен!")
    print(f"🧠 Модель: {AI_MODEL or resolve_model('ai')} | интим-сцены: {INTIM_MODEL or resolve_model('intim')}")
    print(f"💾 Данные сохраняются в {os.path.abspath(DATA_FILE)}")
    print(f"👥 Загружено профилей: {len([k for k in user_data if k != '__settings__'])}")
    print(f"💳 Способы оплаты: {', '.join(available_payment_methods())}")
    print(f"🛍 Mini App магазин: {'включён, ' + WEBAPP_URL + '/shop' if WEBAPP_URL else 'выключен (WEBAPP_URL не задан)'}")
    print("✅ БОТ ГОТОВ К РАБОТЕ!")

    # Нативное меню команд Telegram (кнопка "/" рядом с полем ввода) — всегда на русском,
    # т.к. привязано к языку клиента Telegram, а не к языку, выбранному внутри бота.
    # /feed и /work убраны из видимого списка команд — по фидбэку, кормёжка теперь удобнее
    # через кнопку "Магазин" (в т.ч. Mini App), а /work тоже не то, что нужно тыкать часто.
    # Сами команды при этом продолжают работать, если их набрать руками — просто не подсказываются.
    await bot.set_my_commands([
        BotCommand(command="start", description="Регистрация / главное меню"),
        BotCommand(command="help", description="Список команд"),
        BotCommand(command="games", description="Развлечения с персонажем"),
        BotCommand(command="support", description="Связаться с поддержкой"),
        BotCommand(command="language", description="Сменить язык"),
        BotCommand(command="hot", description="Горячая сцена с персонажем"),
        BotCommand(command="reset_character", description="Сбросить кастомного персонажа"),
        BotCommand(command="switch_personality", description="Сменить мир/пол (SUPER PRO+)"),
        BotCommand(command="switch_style", description="Сменить стиль (SUPER PRO+)"),
    ])

    if WEBAPP_URL:
        asyncio.create_task(run_webapp_server())
        asyncio.create_task(remove_old_keyboards())
        try:
            # Кнопка слева от поля ввода открывает всё приложение (initData у неё есть, в отличие от reply-клавиатуры).
            await bot.set_chat_menu_button(menu_button=MenuButtonWebApp(text="Открыть", web_app=WebAppInfo(url=f"{WEBAPP_URL}/app")))
        except Exception as e:
            logging.warning(f"set_chat_menu_button: {e}")
    asyncio.create_task(check_notifications())
    asyncio.create_task(check_pending_payments())
    await dp.start_polling(bot)


if __name__ == "__main__":
    asyncio.run(main())
